window.DL_QUESTIONS=[{"id":"sign-A1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A1-1\" alt=\"A1 Dangerous bend\" width=\"64\" height=\"64\"></div>","opts":["Level crossing with barriers","Dangerous bend","Roundabout ahead","Level crossing without barriers"],"a":1,"ex":"A1 is <strong>Dangerous bend</strong> (Swedish: <i lang=\"sv\">Varning för farlig kurva</i>). Warns of a dangerous bend and shows which way the bend turns.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A1"],"gen":"sign"},{"id":"sign-A2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A2-1\" alt=\"A2 Several dangerous bends\" width=\"64\" height=\"64\"></div>","opts":["Crossroads (right-hand rule)","Several dangerous bends","Steep descent","Cyclists and moped riders"],"a":1,"ex":"A2 is <strong>Several dangerous bends</strong> (Swedish: <i lang=\"sv\">Varning för flera farliga kurvor</i>). Warns of several dangerous bends and shows which way the first one turns.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A2"],"gen":"sign"},{"id":"sign-A3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A3-1\" alt=\"A3 Steep descent\" width=\"64\" height=\"64\"></div>","opts":["Animals","Steep descent","Falling rocks","Several dangerous bends"],"a":1,"ex":"A3 is <strong>Steep descent</strong> (Swedish: <i lang=\"sv\">Varning för nedförslutning</i>). Warns of a steep downhill slope. The number gives the gradient in per cent and is set to match the actual slope at the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A3"],"gen":"sign"},{"id":"sign-A4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A4-1\" alt=\"A4 Steep ascent\" width=\"64\" height=\"64\"></div>","opts":["Horse riders","Steep ascent","Pedestrian crossing ahead","Crossroads (right-hand rule)"],"a":1,"ex":"A4 is <strong>Steep ascent</strong> (Swedish: <i lang=\"sv\">Varning för stigning</i>). Warns of a steep uphill slope. The number gives the gradient in per cent and is set to match the actual slope at the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A4"],"gen":"sign"},{"id":"sign-A5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A5-1\" alt=\"A5 Road narrows\" width=\"64\" height=\"64\"></div>","opts":["Level crossing with barriers","Road narrows","St Andrew's cross (level crossing)","Children"],"a":1,"ex":"A5 is <strong>Road narrows</strong> (Swedish: <i lang=\"sv\">Varning för avsmalnande väg</i>). Warns that the road or lane gets narrower. The symbol is drawn to match the actual narrowing at the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A5"],"gen":"sign"},{"id":"sign-A6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A6-1\" alt=\"A6 Opening bridge\" width=\"64\" height=\"64\"></div>","opts":["Tramway crossing without barriers","Opening bridge","Low-flying aircraft","Level crossing with barriers"],"a":1,"ex":"A6 is <strong>Opening bridge</strong> (Swedish: <i lang=\"sv\">Varning för bro</i>). Warns of a bridge that can be opened (for example to let boats pass).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A6"],"gen":"sign"},{"id":"sign-A7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A7-1\" alt=\"A7 Quay or river bank\" width=\"64\" height=\"64\"></div>","opts":["Pedestrian crossing ahead","Road works","Quay or river bank","Side wind"],"a":2,"ex":"A7 is <strong>Quay or river bank</strong> (Swedish: <i lang=\"sv\">Varning för kaj</i>). Warns of a place where the road ends at water.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A7"],"gen":"sign"},{"id":"sign-A8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A8-1\" alt=\"A8 Uneven road\" width=\"64\" height=\"64\"></div>","opts":["Steep ascent","Uneven road","Steep descent","Soft verge or high road edge"],"a":1,"ex":"A8 is <strong>Uneven road</strong> (Swedish: <i lang=\"sv\">Varning för ojämn väg</i>). Warns of bumps or damage in the road surface that make it wise to drive more slowly than you otherwise would.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A8"],"gen":"sign"},{"id":"sign-A9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A9-1\" alt=\"A9 Speed bump or dip\" width=\"64\" height=\"64\"></div>","opts":["Steep ascent","Loose stones","Speed bump or dip","Slow-moving vehicles"],"a":2,"ex":"A9 is <strong>Speed bump or dip</strong> (Swedish: <i lang=\"sv\">Varning för farthinder</i>). Warns of a raised hump or a dip that has been built on purpose to make traffic slow down.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A9"],"gen":"sign"},{"id":"sign-A10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A10-1\" alt=\"A10 Slippery road\" width=\"64\" height=\"64\"></div>","opts":["Traffic signals ahead","Slippery road","Animals","Level crossing with barriers"],"a":1,"ex":"A10 is <strong>Slippery road</strong> (Swedish: <i lang=\"sv\">Varning för slirig väg</i>). Warns that the road may be slippery. It is used to warn of slippery snow or ice only if there are special reasons.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A10"],"gen":"sign"},{"id":"sign-A11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A11-1\" alt=\"A11 Loose stones\" width=\"64\" height=\"64\"></div>","opts":["Steep ascent","Loose stones","Quay or river bank","Queues likely"],"a":1,"ex":"A11 is <strong>Loose stones</strong> (Swedish: <i lang=\"sv\">Varning för stenskott</i>). Warns of the risk of stones being thrown up by tyres. It is not used on gravel roads and similar roads, where this is common.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A11"],"gen":"sign"},{"id":"sign-A12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A12-1\" alt=\"A12 Falling rocks\" width=\"64\" height=\"64\"></div>","opts":["Soft verge or high road edge","Falling rocks","Animals","Several dangerous bends"],"a":1,"ex":"A12 is <strong>Falling rocks</strong> (Swedish: <i lang=\"sv\">Varning för stenras</i>). Warns of the risk of rock falls, and that stones from a rock fall may lie on the road. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A12"],"gen":"sign"},{"id":"sign-A13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A13-1\" alt=\"A13 Pedestrian crossing ahead\" width=\"64\" height=\"64\"></div>","opts":["Children","Pedestrian crossing ahead","Queues likely","Several dangerous bends"],"a":1,"ex":"A13 is <strong>Pedestrian crossing ahead</strong> (Swedish: <i lang=\"sv\">Varning för övergångsställe</i>). Warns of a pedestrian crossing ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A13"],"gen":"sign"},{"id":"sign-A14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A14\" alt=\"A14 Pedestrians\" width=\"64\" height=\"64\"></div>","opts":["Queues likely","Pedestrians","Opening bridge","Children"],"a":1,"ex":"A14 is <strong>Pedestrians</strong> (Swedish: <i lang=\"sv\">Varning för gående</i>). Warns of a stretch of road where pedestrians often cross or walk on or beside the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A14"],"gen":"sign"},{"id":"sign-A15","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A15-1\" alt=\"A15 Children\" width=\"64\" height=\"64\"></div>","opts":["Level crossing without barriers","Children","Falling rocks","Queues likely"],"a":1,"ex":"A15 is <strong>Children</strong> (Swedish: <i lang=\"sv\">Varning för barn</i>). Warns of a stretch of road where children often cross or spend time on or beside the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A15"],"gen":"sign"},{"id":"sign-A16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A16-1\" alt=\"A16 Cyclists and moped riders\" width=\"64\" height=\"64\"></div>","opts":["Steep descent","Falling rocks","Cyclists and moped riders","St Andrew's cross (level crossing)"],"a":2,"ex":"A16 is <strong>Cyclists and moped riders</strong> (Swedish: <i lang=\"sv\">Varning för cyklande och mopedförare</i>). Warns of a stretch of road where cyclists or moped riders often cross the road or ride out onto it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A16"],"gen":"sign"},{"id":"sign-A17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A17-1\" alt=\"A17 Skiers\" width=\"64\" height=\"64\"></div>","opts":["Two-way traffic","Skiers","Steep ascent","Soft verge or high road edge"],"a":1,"ex":"A17 is <strong>Skiers</strong> (Swedish: <i lang=\"sv\">Varning för skidåkare</i>). Warns of a place where skiers often cross or spend time on the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A17"],"gen":"sign"},{"id":"sign-A18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A18-1\" alt=\"A18 Horse riders\" width=\"64\" height=\"64\"></div>","opts":["Queues likely","Horse riders","Several dangerous bends","Opening bridge"],"a":1,"ex":"A18 is <strong>Horse riders</strong> (Swedish: <i lang=\"sv\">Varning för ridande</i>). Warns of a stretch of road where people on horseback often cross or spend time on the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A18"],"gen":"sign"},{"id":"sign-A19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A19-1\" alt=\"A19 Animals\" width=\"64\" height=\"64\"></div>","opts":["Several dangerous bends","Animals","Low-flying aircraft","Horse-drawn vehicles"],"a":1,"ex":"A19 is <strong>Animals</strong> (Swedish: <i lang=\"sv\">Varning för djur</i>). Warns of a place or stretch of road where there is a special risk of animals on or beside the road. The basic sign shows an elk (moose); other symbols show other animals.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A19"],"gen":"sign"},{"id":"sign-A20","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A20-1\" alt=\"A20 Road works\" width=\"64\" height=\"64\"></div>","opts":["Opening bridge","Steep ascent","Road works","Level crossing with barriers"],"a":2,"ex":"A20 is <strong>Road works</strong> (Swedish: <i lang=\"sv\">Varning för vägarbete</i>). Warns of a stretch of road where road works or similar work is going on.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A20"],"gen":"sign"},{"id":"sign-A21","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A21-1\" alt=\"A21 End of road works\" width=\"64\" height=\"64\"></div>","opts":["Horse riders","End of road works","Other danger","Several dangerous bends"],"a":1,"ex":"A21 is <strong>End of road works</strong> (Swedish: <i lang=\"sv\">Slut på sträcka med vägarbete</i>). Marks the end of a stretch of road works that was marked with sign A20. It is left out if it is clear anyway where the stretch ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A21"],"gen":"sign"},{"id":"sign-A22","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A22-1\" alt=\"A22 Traffic signals ahead\" width=\"64\" height=\"64\"></div>","opts":["St Andrew's cross (level crossing)","Traffic signals ahead","Slow-moving vehicles","Horse riders"],"a":1,"ex":"A22 is <strong>Traffic signals ahead</strong> (Swedish: <i lang=\"sv\">Varning för flerfärgssignal</i>). Warns of a place where traffic is controlled by traffic lights with three lamps (red, yellow, green). Inside built-up areas it is only put up if there are special reasons.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A22"],"gen":"sign"},{"id":"sign-A23","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A23-1\" alt=\"A23 Low-flying aircraft\" width=\"64\" height=\"64\"></div>","opts":["Crossroads (right-hand rule)","Opening bridge","Low-flying aircraft","Traffic signals ahead"],"a":2,"ex":"A23 is <strong>Low-flying aircraft</strong> (Swedish: <i lang=\"sv\">Varning för lågt flygande flygplan</i>). Warns of low-flying aircraft, for example near the end of a runway.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A23"],"gen":"sign"},{"id":"sign-A24","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A24-1\" alt=\"A24 Side wind\" width=\"64\" height=\"64\"></div>","opts":["Slippery road","Two-way traffic","Side wind","Roundabout ahead"],"a":2,"ex":"A24 is <strong>Side wind</strong> (Swedish: <i lang=\"sv\">Varning för sidvind</i>). Warns of a stretch of road where strong side winds are common. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A24"],"gen":"sign"},{"id":"sign-A25","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A25-1\" alt=\"A25 Two-way traffic\" width=\"64\" height=\"64\"></div>","opts":["Crossroads (right-hand rule)","Two-way traffic","Soft verge or high road edge","Opening bridge"],"a":1,"ex":"A25 is <strong>Two-way traffic</strong> (Swedish: <i lang=\"sv\">Varning för mötande trafik</i>). Warns that a carriageway with one-way traffic becomes a carriageway with traffic in both directions.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A25"],"gen":"sign"},{"id":"sign-A26","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A26-1\" alt=\"A26 Tunnel\" width=\"64\" height=\"64\"></div>","opts":["Low-flying aircraft","Tunnel","Tramway crossing without barriers","Skiers"],"a":1,"ex":"A26 is <strong>Tunnel</strong> (Swedish: <i lang=\"sv\">Varning för tunnel</i>). Warns of a tunnel ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A26"],"gen":"sign"},{"id":"sign-A27","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A27-1\" alt=\"A27 Soft verge or high road edge\" width=\"64\" height=\"64\"></div>","opts":["Pedestrian crossing ahead","Pedestrians","Soft verge or high road edge","Low-flying aircraft"],"a":2,"ex":"A27 is <strong>Soft verge or high road edge</strong> (Swedish: <i lang=\"sv\">Varning för svag vägkant eller hög körbanekant</i>). Warns of a weak road edge, or of a high step down from the edge of the carriageway.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A27"],"gen":"sign"},{"id":"sign-A28","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A28-1\" alt=\"A28 Crossroads (right-hand rule)\" width=\"64\" height=\"64\"></div>","opts":["Steep ascent","Crossroads (right-hand rule)","Horse-drawn vehicles","Level crossing without barriers"],"a":1,"ex":"A28 is <strong>Crossroads (right-hand rule)</strong> (Swedish: <i lang=\"sv\">Varning för vägkorsning</i>). Warns of a junction where the right-hand rule applies, that is, you must give way to vehicles coming from your right (Road Traffic Ordinance, chapter 3, section 18).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A28"],"gen":"sign"},{"id":"sign-A29","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A29-1\" alt=\"A29 Junction where side roads must give way\" width=\"64\" height=\"64\"></div>","opts":["Horse riders","Junction where side roads must give way","St Andrew's cross (level crossing)","Pedestrians"],"a":1,"ex":"A29 is <strong>Junction where side roads must give way</strong> (Swedish: <i lang=\"sv\">Varning för vägkorsning där trafikanter på anslutande väg har väjningsplikt eller stopplikt</i>). Warns of a junction where drivers on the side roads have to give way or stop. You are on the road with priority. The symbol shows the shape of the junction; the wide line is your road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A29"],"gen":"sign"},{"id":"sign-A30","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A30-1\" alt=\"A30 Roundabout ahead\" width=\"64\" height=\"64\"></div>","opts":["Low-flying aircraft","Tunnel","Roundabout ahead","Loose stones"],"a":2,"ex":"A30 is <strong>Roundabout ahead</strong> (Swedish: <i lang=\"sv\">Varning för cirkulationsplats</i>). Warns of a roundabout ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A30"],"gen":"sign"},{"id":"sign-A31","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A31\" alt=\"A31 Slow-moving vehicles\" width=\"64\" height=\"64\"></div>","opts":["Road works","Slow-moving vehicles","Loose stones","Skiers"],"a":1,"ex":"A31 is <strong>Slow-moving vehicles</strong> (Swedish: <i lang=\"sv\">Varning för långsamtgående fordon</i>). Warns of a place where slow vehicles often cross the road or drive out onto it, for example tractors.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A31"],"gen":"sign"},{"id":"sign-A32","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A32-1\" alt=\"A32 Horse-drawn vehicles\" width=\"64\" height=\"64\"></div>","opts":["Pedestrians","Horse-drawn vehicles","Children","Soft verge or high road edge"],"a":1,"ex":"A32 is <strong>Horse-drawn vehicles</strong> (Swedish: <i lang=\"sv\">Varning för fordon med förspänt dragdjur</i>). Warns of a stretch of road where vehicles pulled by animals often cross or travel on the road. Other symbols can be used.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A32"],"gen":"sign"},{"id":"sign-A33","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A33-1\" alt=\"A33 Snowmobiles\" width=\"64\" height=\"64\"></div>","opts":["Level crossing without barriers","Tunnel","Snowmobiles","Several dangerous bends"],"a":2,"ex":"A33 is <strong>Snowmobiles</strong> (Swedish: <i lang=\"sv\">Varning för terrängskotertrafik</i>). Warns of a place where snowmobiles and other off-road scooters often cross the road or drive out onto it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A33"],"gen":"sign"},{"id":"sign-A34","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A34-1\" alt=\"A34 Queues likely\" width=\"64\" height=\"64\"></div>","opts":["Pedestrians","Snowmobiles","Queues likely","Steep descent"],"a":2,"ex":"A34 is <strong>Queues likely</strong> (Swedish: <i lang=\"sv\">Varning för kö</i>). Warns of a stretch of road where there is a risk of queues building up.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A34"],"gen":"sign"},{"id":"sign-A35","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A35-1\" alt=\"A35 Level crossing with barriers\" width=\"64\" height=\"64\"></div>","opts":["Queues likely","Level crossing without barriers","Level crossing with barriers","Traffic signals ahead"],"a":2,"ex":"A35 is <strong>Level crossing with barriers</strong> (Swedish: <i lang=\"sv\">Varning för järnvägskorsning med bommar</i>). Warns of a crossing with a railway or tramway where there are barriers.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A35"],"gen":"sign"},{"id":"sign-A36","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A36-1\" alt=\"A36 Level crossing without barriers\" width=\"64\" height=\"64\"></div>","opts":["Accident","Level crossing without barriers","Other danger","Two-way traffic"],"a":1,"ex":"A36 is <strong>Level crossing without barriers</strong> (Swedish: <i lang=\"sv\">Varning för järnvägskorsning utan bommar</i>). Warns of a railway crossing that has no barriers.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A36"],"gen":"sign"},{"id":"sign-A37","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A37-1\" alt=\"A37 Tramway crossing without barriers\" width=\"64\" height=\"64\"></div>","opts":["Loose stones","Traffic signals ahead","Tramway crossing without barriers","Opening bridge"],"a":2,"ex":"A37 is <strong>Tramway crossing without barriers</strong> (Swedish: <i lang=\"sv\">Varning för korsning med spårväg utan bommar</i>). Warns of a crossing with a tramway that has no barriers.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A37"],"gen":"sign"},{"id":"sign-A39","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A39-1\" alt=\"A39 St Andrew's cross (level crossing)\" width=\"64\" height=\"64\"></div>","opts":["Loose stones","St Andrew's cross (level crossing)","Slippery road","End of road works"],"a":1,"ex":"A39 is <strong>St Andrew's cross (level crossing)</strong> (Swedish: <i lang=\"sv\">Kryssmärke</i>). Marks a crossing with a railway or tramway with one or more tracks. It is placed immediately before a level crossing. It may be left out on a private road with little traffic, where that can be done without danger. It can also be used at other crossings with a railway or tramway.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A39"],"gen":"sign"},{"id":"sign-A40","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A40-1\" alt=\"A40 Other danger\" width=\"64\" height=\"64\"></div>","opts":["Side wind","Other danger","Animals","Loose stones"],"a":1,"ex":"A40 is <strong>Other danger</strong> (Swedish: <i lang=\"sv\">Varning för annan fara</i>). Warns of a danger that no other warning sign covers. An additional panel below it says what the danger is.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A40"],"gen":"sign"},{"id":"sign-A41","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A41\" alt=\"A41 Accident\" width=\"64\" height=\"64\"></div>","opts":["Several dangerous bends","Accident","Slow-moving vehicles","Opening bridge"],"a":1,"ex":"A41 is <strong>Accident</strong> (Swedish: <i lang=\"sv\">Varning för olycka</i>). Warns that there has been a traffic accident on the road ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A41"],"gen":"sign"},{"id":"sign-B1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B1-1\" alt=\"B1 Give way\" width=\"64\" height=\"64\"></div>","opts":["Pedestrian crossing","Give way","End of main road","Main road"],"a":1,"ex":"B1 is <strong>Give way</strong> (Swedish: <i lang=\"sv\">Väjningsplikt</i>). You must give way to vehicles on the road or route you are about to cross or enter. Chapter 3, section 5 of the Road Traffic Ordinance applies – show clearly in good time that you will give way by slowing down or stopping, and go on only when it causes no danger or obstruction. With additional panel T2 (distance) it warns in advance of a give-way point; with T3 it warns in advance of a stop sign. Panel T13 means that all roads into the junction have to give way.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B1"],"gen":"sign"},{"id":"sign-B2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B2-1\" alt=\"B2 Stop\" width=\"64\" height=\"64\"></div>","opts":["End of main road","Stop","Pedestrian crossing","Cycle crossing"],"a":1,"ex":"B2 is <strong>Stop</strong> (Swedish: <i lang=\"sv\">Stopplikt</i>). You must stop before you drive into the crossing road, route or track area. Chapter 3, section 19 of the Road Traffic Ordinance applies – stop at the stop line, or if there is none, immediately before you enter the crossing road. Panel T14 means that all roads into the junction must stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B2"],"gen":"sign"},{"id":"sign-B3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B3-1\" alt=\"B3 Pedestrian crossing\" width=\"64\" height=\"64\"></div>","opts":["Main road","Pedestrian crossing","Cycle crossing","Oncoming traffic must give way"],"a":1,"ex":"B3 is <strong>Pedestrian crossing</strong> (Swedish: <i lang=\"sv\">Övergångsställe</i>). Marks a pedestrian crossing. The two versions mean exactly the same and can be used alone or together. At an unguarded crossing (one without traffic lights or police), drivers must give way to pedestrians who are on the crossing or about to step onto it, and pedestrians must take account of the distance and speed of approaching vehicles.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B3"],"gen":"sign"},{"id":"sign-B4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B4-1\" alt=\"B4 Main road\" width=\"64\" height=\"64\"></div>","opts":["Oncoming traffic must give way","End of main road","Main road","Pedestrian crossing"],"a":2,"ex":"B4 is <strong>Main road</strong> (Swedish: <i lang=\"sv\">Huvudled</i>). Marks the start of a main road (priority road). Traffic coming onto it from side roads must give way. The sign is repeated after each junction, unless it is clear anyway that the main road continues. Exits from places such as car parks, petrol stations and private property do not count as junctions here.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B4"],"gen":"sign"},{"id":"sign-B5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B5-1\" alt=\"B5 End of main road\" width=\"64\" height=\"64\"></div>","opts":["Main road","End of main road","Give way to oncoming traffic","Stop"],"a":1,"ex":"B5 is <strong>End of main road</strong> (Swedish: <i lang=\"sv\">Huvudled upphör</i>). Marks the end of a main road (priority road). After this sign you no longer have priority over side roads because of the main road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B5"],"gen":"sign"},{"id":"sign-B6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B6-1\" alt=\"B6 Give way to oncoming traffic\" width=\"64\" height=\"64\"></div>","opts":["Pedestrian crossing","Cycle crossing","Give way to oncoming traffic","Stop"],"a":2,"ex":"B6 is <strong>Give way to oncoming traffic</strong> (Swedish: <i lang=\"sv\">Väjningsplikt mot mötande trafik</i>). You may not drive into the stretch ahead (often a narrow section) if doing so would hinder vehicles coming towards you. Let them pass first.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B6"],"gen":"sign"},{"id":"sign-B7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B7-1\" alt=\"B7 Oncoming traffic must give way\" width=\"64\" height=\"64\"></div>","opts":["Main road","Oncoming traffic must give way","Stop","Give way to oncoming traffic"],"a":1,"ex":"B7 is <strong>Oncoming traffic must give way</strong> (Swedish: <i lang=\"sv\">Mötande trafik har väjningsplikt</i>). You have priority over oncoming traffic on the narrow stretch ahead. Drivers coming towards you must give way.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B7"],"gen":"sign"},{"id":"sign-B8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B8-1\" alt=\"B8 Cycle crossing\" width=\"64\" height=\"64\"></div>","opts":["Stop","End of main road","Cycle crossing","Give way to oncoming traffic"],"a":2,"ex":"B8 is <strong>Cycle crossing</strong> (Swedish: <i lang=\"sv\">Cykelöverfart</i>). Marks a cycle crossing (cykelöverfart). Drivers must give way to cyclists and riders of class II mopeds who are on the crossing or about to ride onto it. Cyclists must take account of the distance and speed of approaching vehicles.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B8"],"gen":"sign"},{"id":"sign-C1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C1-1\" alt=\"C1 No entry\" width=\"64\" height=\"64\"></div>","opts":["No off-road vehicles","No entry","Stop for the reason given","No horse-drawn vehicles"],"a":1,"ex":"C1 is <strong>No entry</strong> (Swedish: <i lang=\"sv\">Förbud mot infart med fordon</i>). Driving any vehicle into the road from this direction is prohibited. It is used, for example, at the far end of a one-way street.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C1"],"gen":"sign"},{"id":"sign-C2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C2-1\" alt=\"C2 No vehicles\" width=\"64\" height=\"64\"></div>","opts":["No pedestrians","No motorcycles or class I mopeds","No vehicles","No motor vehicles (except class II mopeds)"],"a":2,"ex":"C2 is <strong>No vehicles</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med fordon</i>). Traffic with all vehicles is prohibited, in both directions.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C2"],"gen":"sign"},{"id":"sign-C3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C3-1\" alt=\"C3 No motor vehicles (except class II mopeds)\" width=\"64\" height=\"64\"></div>","opts":["No motorcycles or class I mopeds","No motor vehicles with more than two wheels","No motor vehicles (except class II mopeds)","No vehicles"],"a":2,"ex":"C3 is <strong>No motor vehicles (except class II mopeds)</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med annat motordrivet fordon än moped klass II</i>). Traffic with motor vehicles other than class II mopeds is prohibited. If class II mopeds are also prohibited, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C3"],"gen":"sign"},{"id":"sign-C4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C4-1\" alt=\"C4 No motor vehicles with more than two wheels\" width=\"64\" height=\"64\"></div>","opts":["End of temporary speed limit","End of no overtaking","No motor vehicles with more than two wheels","Special rules for stopping and parking"],"a":2,"ex":"C4 is <strong>No motor vehicles with more than two wheels</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med motordrivet fordon med fler än två hjul</i>). Traffic with motor vehicles that have more than two wheels is prohibited – for example cars. Two-wheeled motorcycles and mopeds may still use the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C4"],"gen":"sign"},{"id":"sign-C5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C5-1\" alt=\"C5 No motorcycles or class I mopeds\" width=\"64\" height=\"64\"></div>","opts":["End of no overtaking","No motorcycles or class I mopeds","No motor vehicles with more than two wheels","No vehicles"],"a":1,"ex":"C5 is <strong>No motorcycles or class I mopeds</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med motorcykel och moped klass I</i>). Traffic with motorcycles and class I mopeds is prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C5"],"gen":"sign"},{"id":"sign-C6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C6-1\" alt=\"C6 No motor vehicles with a trailer\" width=\"64\" height=\"64\"></div>","opts":["No stopping or parking","Date parking","No motor vehicles with a trailer","No pedestrians"],"a":2,"ex":"C6 is <strong>No motor vehicles with a trailer</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med motordrivet fordon med tillkopplad släpvagn</i>). Traffic with motor vehicles towing a trailer is prohibited. The ban does not cover semi-trailers or light single-axle trailers of the kind called släpkärra unless a panel says so. If the ban only covers combinations whose trailer weighs more than a certain total weight, panel T5 shows that weight.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C6"],"gen":"sign"},{"id":"sign-C7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C7-1\" alt=\"C7 No heavy trucks\" width=\"64\" height=\"64\"></div>","opts":["No horse-drawn vehicles","No heavy trucks","End of turning place","No vehicles"],"a":1,"ex":"C7 is <strong>No heavy trucks</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med tung lastbil</i>). Traffic with heavy trucks (total weight over 3,500 kg) is prohibited. If the ban also covers light trucks, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C7"],"gen":"sign"},{"id":"sign-C8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C8-1\" alt=\"C8 No tractors or class II motor implements\" width=\"64\" height=\"64\"></div>","opts":["Width limit","No tractors or class II motor implements","No motor vehicles (except class II mopeds)","No horse riding"],"a":1,"ex":"C8 is <strong>No tractors or class II motor implements</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med traktor och motorredskap klass II</i>). Traffic with tractors (class a) and class II motor implements (machines built for at most 30 km/h) is prohibited. If the ban also covers class b tractors or class I motor implements, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C8"],"gen":"sign"},{"id":"sign-C9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C9-1\" alt=\"C9 No vehicles carrying dangerous goods\" width=\"64\" height=\"64\"></div>","opts":["No vehicles","No vehicles carrying dangerous goods","Bearing capacity class","No off-road vehicles"],"a":1,"ex":"C9 is <strong>No vehicles carrying dangerous goods</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med fordon lastat med farligt gods</i>). Traffic with vehicles carrying a load that must be marked with orange plates under the rules on transport of dangerous goods is prohibited. With panel T23 the sign shows the category of a road tunnel.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C9"],"gen":"sign"},{"id":"sign-C10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C10-1\" alt=\"C10 No cycles or class II mopeds\" width=\"64\" height=\"64\"></div>","opts":["No heavy trucks","Special-purpose place","No cycles or class II mopeds","Minimum distance"],"a":2,"ex":"C10 is <strong>No cycles or class II mopeds</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med cykel och moped klass II</i>). Traffic with bicycles and class II mopeds is prohibited. If class I mopeds are also banned, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C10"],"gen":"sign"},{"id":"sign-C11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C11-1\" alt=\"C11 No class II mopeds\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with more than two wheels","No class II mopeds","End of turning place","Weight limit for a vehicle or combination"],"a":1,"ex":"C11 is <strong>No class II mopeds</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med moped klass II</i>). Traffic with class II mopeds is prohibited. If class I mopeds are also banned, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C11"],"gen":"sign"},{"id":"sign-C12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C12-1\" alt=\"C12 No horse-drawn vehicles\" width=\"64\" height=\"64\"></div>","opts":["No vehicles","No horse-drawn vehicles","No parking on even dates","Minimum distance"],"a":1,"ex":"C12 is <strong>No horse-drawn vehicles</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med fordon förspänt med dragdjur</i>). Traffic with vehicles pulled by animals is prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C12"],"gen":"sign"},{"id":"sign-C13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C13-1\" alt=\"C13 No off-road vehicles\" width=\"64\" height=\"64\"></div>","opts":["No motorcycles or class I mopeds","No parking","No off-road vehicles","No vehicles"],"a":2,"ex":"C13 is <strong>No off-road vehicles</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med terrängmotorfordon och terrängsläp</i>). Traffic with off-road motor vehicles (such as snowmobiles) and off-road trailers is prohibited. If the ban does not cover terrain vehicles over 450 kg (terrängvagn), a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C13"],"gen":"sign"},{"id":"sign-C14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C14-1\" alt=\"C14 No horse riding\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles (except class II mopeds)","No horse riding","Special rules for stopping and parking","No class II mopeds"],"a":1,"ex":"C14 is <strong>No horse riding</strong> (Swedish: <i lang=\"sv\">Förbud mot ridning</i>). Riding is prohibited. If leading a horse is also prohibited, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C14"],"gen":"sign"},{"id":"sign-C15","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C15-1\" alt=\"C15 No pedestrians\" width=\"64\" height=\"64\"></div>","opts":["End of turning place","No pedestrians","No motor vehicles with more than two wheels","No motor vehicles with studded tyres"],"a":1,"ex":"C15 is <strong>No pedestrians</strong> (Swedish: <i lang=\"sv\">Förbud mot gångtrafik</i>). Pedestrian traffic is prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C15"],"gen":"sign"},{"id":"sign-C16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C16-1\" alt=\"C16 Width limit\" width=\"64\" height=\"64\"></div>","opts":["No horse-drawn vehicles","Width limit","No pedestrians","No U-turns"],"a":1,"ex":"C16 is <strong>Width limit</strong> (Swedish: <i lang=\"sv\">Begränsad fordonsbredd</i>). Vehicles wider than the width shown on the sign are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C16"],"gen":"sign"},{"id":"sign-C17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C17-1\" alt=\"C17 Height limit\" width=\"64\" height=\"64\"></div>","opts":["Bearing capacity class","Triple axle load limit","Height limit","Weight limit for a vehicle or combination"],"a":2,"ex":"C17 is <strong>Height limit</strong> (Swedish: <i lang=\"sv\">Begränsad fordonshöjd</i>). Vehicles higher than the height shown on the sign are prohibited. It is used where the free height is less than 4.5 metres.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C17"],"gen":"sign"},{"id":"sign-C18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C18-1\" alt=\"C18 Length limit\" width=\"64\" height=\"64\"></div>","opts":["No heavy trucks","Length limit","Minimum distance","Triple axle load limit"],"a":1,"ex":"C18 is <strong>Length limit</strong> (Swedish: <i lang=\"sv\">Begränsad fordonslängd</i>). Vehicles or vehicle combinations longer than the length shown on the sign are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C18"],"gen":"sign"},{"id":"sign-C19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C19-1\" alt=\"C19 Minimum distance\" width=\"64\" height=\"64\"></div>","opts":["End of turning place","Minimum distance","Date parking","No horse riding"],"a":1,"ex":"C19 is <strong>Minimum distance</strong> (Swedish: <i lang=\"sv\">Minsta avstånd</i>). It is prohibited to keep a shorter distance than the one shown to the motor vehicle in front of you going in the same direction.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C19"],"gen":"sign"},{"id":"sign-C20","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C20-1\" alt=\"C20 Weight limit for a vehicle\" width=\"64\" height=\"64\"></div>","opts":["No class II mopeds","No cycles or class II mopeds","Weight limit for a vehicle","No motor vehicles with more than two wheels"],"a":2,"ex":"C20 is <strong>Weight limit for a vehicle</strong> (Swedish: <i lang=\"sv\">Begränsad bruttovikt på fordon</i>). Vehicles whose gross weight (the actual weight at that moment, load included) is higher than the weight shown are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C20"],"gen":"sign"},{"id":"sign-C21","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C21-1\" alt=\"C21 Weight limit for a vehicle or combination\" width=\"64\" height=\"64\"></div>","opts":["End of no overtaking by heavy trucks","Weight limit for a vehicle or combination","No vehicles","Minimum distance"],"a":1,"ex":"C21 is <strong>Weight limit for a vehicle or combination</strong> (Swedish: <i lang=\"sv\">Begränsad bruttovikt på fordon och fordonståg</i>). Vehicles and vehicle combinations whose gross weight (actual weight, load included) is higher than the weight shown are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C21"],"gen":"sign"},{"id":"sign-C23","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C23-1\" alt=\"C23 Axle load limit\" width=\"64\" height=\"64\"></div>","opts":["Bearing capacity class","Axle load limit","No overtaking","Speed limit"],"a":1,"ex":"C23 is <strong>Axle load limit</strong> (Swedish: <i lang=\"sv\">Begränsat axeltryck</i>). The highest axle load allowed (the weight the wheels on one axle put on the road) is shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C23"],"gen":"sign"},{"id":"sign-C24","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C24-1\" alt=\"C24 Bogie load limit\" width=\"64\" height=\"64\"></div>","opts":["No U-turns","Date parking","Bogie load limit","No off-road vehicles"],"a":2,"ex":"C24 is <strong>Bogie load limit</strong> (Swedish: <i lang=\"sv\">Begränsat boggitryck</i>). The highest bogie load allowed (the weight that two axles less than 2 metres apart put on the road) is shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C24"],"gen":"sign"},{"id":"sign-C25","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C25-1\" alt=\"C25 No turning\" width=\"64\" height=\"64\"></div>","opts":["No cycles or class II mopeds","No motor vehicles with more than two wheels","No turning","End of turning place"],"a":2,"ex":"C25 is <strong>No turning</strong> (Swedish: <i lang=\"sv\">Förbud mot sväng i korsning</i>). Turning in the direction shown is prohibited at the junction (or similar place) where the sign stands or that it is placed before. It can cover several junctions; the length of the stretch is then shown on a panel. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C25"],"gen":"sign"},{"id":"sign-C26","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C26-1\" alt=\"C26 No U-turns\" width=\"64\" height=\"64\"></div>","opts":["Stop for the reason given","No U-turns","Speed limit","No vehicles"],"a":1,"ex":"C26 is <strong>No U-turns</strong> (Swedish: <i lang=\"sv\">Förbud mot U-sväng</i>). U-turns are prohibited at the junction (or similar place) where the sign stands or that it is placed before. It can cover several junctions; the length of the stretch is then shown on a panel.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C26"],"gen":"sign"},{"id":"sign-C27","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C27-1\" alt=\"C27 No overtaking\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with a trailer","No overtaking","No overtaking by heavy trucks","End of no overtaking"],"a":1,"ex":"C27 is <strong>No overtaking</strong> (Swedish: <i lang=\"sv\">Förbud mot omkörning</i>). It is prohibited to overtake motor vehicles other than two-wheeled mopeds and two-wheeled motorcycles without a sidecar. The ban applies on the road where the sign is placed, until sign C28 (end of no overtaking).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C27"],"gen":"sign"},{"id":"sign-C28","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C28-1\" alt=\"C28 End of no overtaking\" width=\"64\" height=\"64\"></div>","opts":["Special-purpose place","End of no overtaking","No parking","No off-road vehicles"],"a":1,"ex":"C28 is <strong>End of no overtaking</strong> (Swedish: <i lang=\"sv\">Slut på förbud mot omkörning</i>). Marks the end of the overtaking ban that started with sign C27.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C28"],"gen":"sign"},{"id":"sign-C29","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C29-1\" alt=\"C29 No overtaking by heavy trucks\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with more than two wheels","No overtaking by heavy trucks","Special rules for stopping and parking","No motor vehicles (except class II mopeds)"],"a":1,"ex":"C29 is <strong>No overtaking by heavy trucks</strong> (Swedish: <i lang=\"sv\">Förbud mot omkörning med tung lastbil</i>). Drivers of heavy trucks may not overtake motor vehicles other than two-wheeled mopeds and two-wheeled motorcycles without a sidecar. The ban applies until sign C30.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C29"],"gen":"sign"},{"id":"sign-C30","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C30-1\" alt=\"C30 End of no overtaking by heavy trucks\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with a trailer","End of no overtaking by heavy trucks","No motorcycles or class I mopeds","No vehicles"],"a":1,"ex":"C30 is <strong>End of no overtaking by heavy trucks</strong> (Swedish: <i lang=\"sv\">Slut på förbud mot omkörning med tung lastbil</i>). Marks the end of the overtaking ban for heavy trucks that started with sign C29.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C30"],"gen":"sign"},{"id":"sign-C31","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C31-3\" alt=\"C31 Speed limit\" width=\"64\" height=\"64\"></div>","opts":["Axle load limit","Special rules for stopping and parking","Speed limit","No horse riding"],"a":2,"ex":"C31 is <strong>Speed limit</strong> (Swedish: <i lang=\"sv\">Hastighetsbegränsning</i>). You may not drive faster than the speed shown, in km/h. The limit applies until another speed limit sign, sign C32 (end of temporary speed limit), sign E7 (pedestrian street) or sign E9 (walking-speed area). The sign does not have to be repeated after a junction if the crossing road has the same limit.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C31"],"gen":"sign"},{"id":"sign-C32","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C32-3\" alt=\"C32 End of temporary speed limit\" width=\"64\" height=\"64\"></div>","opts":["Weight limit for a vehicle or combination","End of temporary speed limit","Bearing capacity class","No vehicles"],"a":1,"ex":"C32 is <strong>End of temporary speed limit</strong> (Swedish: <i lang=\"sv\">Tillfällig hastighetsbegränsning upphör</i>). Marks the end of a temporary speed limit that was shown with sign C31. After it, the speed limit that applied before the temporary limit applies again.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C32"],"gen":"sign"},{"id":"sign-C33","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C33-1\" alt=\"C33 Stop at customs\" width=\"64\" height=\"64\"></div>","opts":["No heavy trucks","No motor vehicles with more than two wheels","Stop at customs","No motor vehicles with studded tyres"],"a":2,"ex":"C33 is <strong>Stop at customs</strong> (Swedish: <i lang=\"sv\">Stopp vid tull</i>). You must stop for customs formalities, at the stop line or, if there is none, at the sign. The text below the bar is given in a suitable language.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C33"],"gen":"sign"},{"id":"sign-C34","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C34\" alt=\"C34 Stop for the reason given\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with studded tyres","Stop for the reason given","Bearing capacity class","Special-purpose place"],"a":1,"ex":"C34 is <strong>Stop for the reason given</strong> (Swedish: <i lang=\"sv\">Stopp för angivet ändamål</i>). You must stop for the reason written below the bar – at the stop line or, if there is none, at the sign. If the sign stands before a traffic signal (STOPP SIGNAL), vehicles that are to pass the signal must stop when it shows red.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C34"],"gen":"sign"},{"id":"sign-C35","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C35-1\" alt=\"C35 No parking\" width=\"64\" height=\"64\"></div>","opts":["No overtaking","End of no overtaking by heavy trucks","No parking","No stopping or parking"],"a":2,"ex":"C35 is <strong>No parking</strong> (Swedish: <i lang=\"sv\">Förbud mot att parkera fordon</i>). Parking is prohibited on the side of the road where the sign stands. The ban starts at the sign and applies as shown on a panel, or until another stopping or parking rule is signed, until the next junction, or until a matching sign with panel T11 (arrow pointing down). If another rule applies on a shorter stretch, the ban applies again after it without a new sign. The sign does not give you the right to stop where stopping is prohibited by the Road Traffic Ordinance.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C35"],"gen":"sign"},{"id":"sign-C36","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C36-1\" alt=\"C36 No parking on odd dates\" width=\"64\" height=\"64\"></div>","opts":["No U-turns","No parking on odd dates","Turning place","Bogie load limit"],"a":1,"ex":"C36 is <strong>No parking on odd dates</strong> (Swedish: <i lang=\"sv\">Förbud mot att parkera fordon på dag med udda datum</i>). Parking is prohibited on days with an odd date (1st, 3rd, 5th …). Otherwise the same rules as for sign C35 apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C36"],"gen":"sign"},{"id":"sign-C37","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C37-1\" alt=\"C37 No parking on even dates\" width=\"64\" height=\"64\"></div>","opts":["Weight limit for a vehicle","No motor vehicles with more than two wheels","No parking on even dates","No cycles or class II mopeds"],"a":2,"ex":"C37 is <strong>No parking on even dates</strong> (Swedish: <i lang=\"sv\">Förbud mot att parkera fordon på dag med jämnt datum</i>). Parking is prohibited on days with an even date (2nd, 4th, 6th …). Otherwise the same rules as for sign C35 apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C37"],"gen":"sign"},{"id":"sign-C38","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C38-1\" alt=\"C38 Date parking\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with a trailer","Date parking","No heavy trucks","No U-turns"],"a":1,"ex":"C38 is <strong>Date parking</strong> (Swedish: <i lang=\"sv\">Datumparkering</i>). Parking is prohibited on days with an even date on the side of the road with even house numbers, and on days with an odd date on the side with odd house numbers. Otherwise the same rules as for sign C35 apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C38"],"gen":"sign"},{"id":"sign-C39","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C39-1\" alt=\"C39 No stopping or parking\" width=\"64\" height=\"64\"></div>","opts":["No parking","No stopping or parking","No heavy trucks","No vehicles"],"a":1,"ex":"C39 is <strong>No stopping or parking</strong> (Swedish: <i lang=\"sv\">Förbud mot att stanna och parkera fordon</i>). Both stopping and parking are prohibited. The same rules as for sign C35 apply to where the ban starts and ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C39"],"gen":"sign"},{"id":"sign-C40","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C40-1\" alt=\"C40 Special-purpose place\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with a trailer","Special-purpose place","No horse riding","No vehicles"],"a":1,"ex":"C40 is <strong>Special-purpose place</strong> (Swedish: <i lang=\"sv\">Ändamålsplats</i>). A place reserved for a stated purpose. Vehicles may not park or stop there except for that purpose, but may stop briefly to let people get in or out if this does not hinder the purpose. If the purpose is given as lastplats, it means loading or unloading of heavy or bulky goods.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C40"],"gen":"sign"},{"id":"sign-C42","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C42-1\" alt=\"C42 Turning place\" width=\"64\" height=\"64\"></div>","opts":["Bogie load limit","Turning place","No horse-drawn vehicles","No motor vehicles with more than two wheels"],"a":1,"ex":"C42 is <strong>Turning place</strong> (Swedish: <i lang=\"sv\">Vändplats</i>). Marks a place meant for turning vehicles around, where parking is prohibited. If the no-stopping symbol (C39) is shown in the sign instead, both stopping and parking are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C42"],"gen":"sign"},{"id":"sign-C44","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C44\" alt=\"C44 No motor vehicles with studded tyres\" width=\"64\" height=\"64\"></div>","opts":["No parking","End of temporary speed limit","No motor vehicles with studded tyres","No motor vehicles (except class II mopeds)"],"a":2,"ex":"C44 is <strong>No motor vehicles with studded tyres</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med annat motordrivet fordon med dubbdäck än moped klass II</i>). Traffic with motor vehicles that have studded tyres is prohibited, except class II mopeds. If class II mopeds are also banned, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C44"],"gen":"sign"},{"id":"sign-C46","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C46\" alt=\"C46 Triple axle load limit\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with more than two wheels","Triple axle load limit","No overtaking","No cycles or class II mopeds"],"a":1,"ex":"C46 is <strong>Triple axle load limit</strong> (Swedish: <i lang=\"sv\">Begränsat trippelaxeltryck</i>). The highest triple axle load allowed (the weight that three axles close together put on the road) is shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C46"],"gen":"sign"},{"id":"sign-D1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D1-1\" alt=\"D1 Mandatory direction\" width=\"64\" height=\"64\"></div>","opts":["Footpath","Mandatory direction","Mandatory direction for vehicles with dangerous goods","Cycle track"],"a":1,"ex":"D1 is <strong>Mandatory direction</strong> (Swedish: <i lang=\"sv\">Påbjuden körriktning</i>). Vehicles may only be driven in the direction of the arrow, or, where there are two arrows, in the direction of either arrow. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D1"],"gen":"sign"},{"id":"sign-D2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D2-1\" alt=\"D2 Pass this side\" width=\"64\" height=\"64\"></div>","opts":["Bus lane","Pass this side","Cycle track","Footpath"],"a":1,"ex":"D2 is <strong>Pass this side</strong> (Swedish: <i lang=\"sv\">Påbjuden körbana</i>). Vehicles may only pass the sign on the side the arrow points to, or where there are two arrows, on either side. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D2"],"gen":"sign"},{"id":"sign-D3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D3-1\" alt=\"D3 Roundabout\" width=\"64\" height=\"64\"></div>","opts":["Pass this side","Bus lane","Roundabout","Separated paths for pedestrians and cyclists"],"a":2,"ex":"D3 is <strong>Roundabout</strong> (Swedish: <i lang=\"sv\">Cirkulationsplats</i>). Marks a roundabout (cirkulationsplats). Drive anticlockwise around the centre, and give way to every vehicle already in the roundabout when you enter.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D3"],"gen":"sign"},{"id":"sign-D4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D4-1\" alt=\"D4 Cycle track\" width=\"64\" height=\"64\"></div>","opts":["Footpath","Cycle track","Pass this side","Roundabout"],"a":1,"ex":"D4 is <strong>Cycle track</strong> (Swedish: <i lang=\"sv\">Påbjuden cykelbana</i>). Marks a track for cyclists (and class II mopeds unless a panel says otherwise). Other traffic is not allowed on it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D4"],"gen":"sign"},{"id":"sign-D5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D5-1\" alt=\"D5 Footpath\" width=\"64\" height=\"64\"></div>","opts":["End of compulsory path, lane or route","Footpath","Cycle track","Separated paths for pedestrians and cyclists"],"a":1,"ex":"D5 is <strong>Footpath</strong> (Swedish: <i lang=\"sv\">Påbjuden gångbana</i>). Marks a path for pedestrians only.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D5"],"gen":"sign"},{"id":"sign-D6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D6-1\" alt=\"D6 Shared path for pedestrians and cyclists\" width=\"64\" height=\"64\"></div>","opts":["Pass this side","Shared path for pedestrians and cyclists","Footpath","Cycle track"],"a":1,"ex":"D6 is <strong>Shared path for pedestrians and cyclists</strong> (Swedish: <i lang=\"sv\">Påbjuden gång- och cykelbana</i>). Marks a path shared by pedestrians and cyclists (and class II mopeds unless a panel says otherwise).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D6"],"gen":"sign"},{"id":"sign-D7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D7-1\" alt=\"D7 Separated paths for pedestrians and cyclists\" width=\"64\" height=\"64\"></div>","opts":["Pass this side","Cycle track","Separated paths for pedestrians and cyclists","Bridle path"],"a":2,"ex":"D7 is <strong>Separated paths for pedestrians and cyclists</strong> (Swedish: <i lang=\"sv\">Påbjudna gång- och cykelbanor</i>). Marks paths that are divided by a road marking, kerb or similar into one part for pedestrians and one for cyclists. The position of the symbols on the sign shows which side is for whom. Class II mopeds may use the cycle part unless a panel says otherwise.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D7"],"gen":"sign"},{"id":"sign-D8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D8-1\" alt=\"D8 Bridle path\" width=\"64\" height=\"64\"></div>","opts":["Mandatory direction for vehicles with dangerous goods","Bridle path","Shared path for pedestrians and cyclists","End of compulsory path, lane or route"],"a":1,"ex":"D8 is <strong>Bridle path</strong> (Swedish: <i lang=\"sv\">Påbjuden ridväg</i>). Marks a path for horse riding. Walking is also allowed on it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D8"],"gen":"sign"},{"id":"sign-D9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D9-1\" alt=\"D9 Route for off-road vehicles\" width=\"64\" height=\"64\"></div>","opts":["Pass this side","Route for off-road vehicles","Cycle track","End of compulsory path, lane or route"],"a":1,"ex":"D9 is <strong>Route for off-road vehicles</strong> (Swedish: <i lang=\"sv\">Påbjuden led för terrängmotorfordon och terrängsläp</i>). Marks a route for off-road motor vehicles (such as snowmobiles) and off-road trailers. Walking is also allowed on it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D9"],"gen":"sign"},{"id":"sign-D10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D10-1\" alt=\"D10 Bus lane\" width=\"64\" height=\"64\"></div>","opts":["Shared path for pedestrians and cyclists","Mandatory direction for vehicles with dangerous goods","Bus lane","Route for off-road vehicles"],"a":2,"ex":"D10 is <strong>Bus lane</strong> (Swedish: <i lang=\"sv\">Påbjudet körfält eller körbana för fordon i linjetrafik med flera</i>). Marks a lane or carriageway for vehicles in scheduled services (buses) and the others allowed by the Road Traffic Ordinance – bicycles and class II mopeds may use it if it is on the right-hand side. A panel can allow other vehicles, such as taxis.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D10"],"gen":"sign"},{"id":"sign-D11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D11-1\" alt=\"D11 End of compulsory path, lane or route\" width=\"64\" height=\"64\"></div>","opts":["Cycle track","End of compulsory path, lane or route","Roundabout","Pass this side"],"a":1,"ex":"D11 is <strong>End of compulsory path, lane or route</strong> (Swedish: <i lang=\"sv\">Slut på påbjuden bana, körfält, väg eller led</i>). Marks the end of a path, lane, road or route marked with one of the signs D4–D10. It is left out if it is clear anyway that the rule has ended. The symbol in it is the same as on the sign that started the stretch.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D11"],"gen":"sign"},{"id":"sign-E1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E-11\" alt=\"E1 Motorway\" width=\"64\" height=\"64\"></div>","opts":["End of expressway","Motorway","Emergency exit","Automatic traffic surveillance"],"a":1,"ex":"E1 is <strong>Motorway</strong> (Swedish: <i lang=\"sv\">Motorväg</i>). Marks the start of a motorway (motorväg), where the special motorway rules apply. Used as an advance notice, a panel gives the distance to where the motorway begins. The sign can also appear inside a direction sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E1"],"gen":"sign"},{"id":"sign-E2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E2-1\" alt=\"E2 End of motorway\" width=\"64\" height=\"64\"></div>","opts":["Zone sign","Environmental zone","End of motorway","Pedestrian street"],"a":2,"ex":"E2 is <strong>End of motorway</strong> (Swedish: <i lang=\"sv\">Motorväg upphör</i>). Marks the end of a motorway. Used as an advance notice, a panel gives the distance. It is not used where a motorway turns into an expressway (motortrafikled).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E2"],"gen":"sign"},{"id":"sign-E3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E3-1\" alt=\"E3 Expressway\" width=\"64\" height=\"64\"></div>","opts":["Taxi rank","Expressway","One-way traffic","End of motorway"],"a":1,"ex":"E3 is <strong>Expressway</strong> (Swedish: <i lang=\"sv\">Motortrafikled</i>). Marks the start of an expressway (motortrafikled) – a road for fast motor traffic with no level junctions, where most motorway rules apply. Used as an advance notice, a panel gives the distance. The sign can also appear inside a direction sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E3"],"gen":"sign"},{"id":"sign-E4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E4-1\" alt=\"E4 End of expressway\" width=\"64\" height=\"64\"></div>","opts":["Built-up area","End of expressway","End of motorway","Recommended lower speed"],"a":1,"ex":"E4 is <strong>End of expressway</strong> (Swedish: <i lang=\"sv\">Motortrafikled upphör</i>). Marks the end of an expressway. Used as an advance notice, a panel gives the distance. It is not used where an expressway turns into a motorway.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E4"],"gen":"sign"},{"id":"sign-E5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E5-1\" alt=\"E5 Built-up area\" width=\"64\" height=\"64\"></div>","opts":["Recommended lower speed","End of pedestrian street","Built-up area","End of environmental zone"],"a":2,"ex":"E5 is <strong>Built-up area</strong> (Swedish: <i lang=\"sv\">Tättbebyggt område</i>). Marks the start of a built-up area (tättbebyggt område). The name of the place may be shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E5"],"gen":"sign"},{"id":"sign-E6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E6-1\" alt=\"E6 End of built-up area\" width=\"64\" height=\"64\"></div>","opts":["Zone sign","Expressway","End of built-up area","End of recommended lower speed"],"a":2,"ex":"E6 is <strong>End of built-up area</strong> (Swedish: <i lang=\"sv\">Tättbebyggt område upphör</i>). Marks the end of a built-up area. The name of the place may be shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E6"],"gen":"sign"},{"id":"sign-E7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E7-1\" alt=\"E7 Pedestrian street\" width=\"64\" height=\"64\"></div>","opts":["End of recommended lower speed","Pedestrian street","Zone sign","Passing place"],"a":1,"ex":"E7 is <strong>Pedestrian street</strong> (Swedish: <i lang=\"sv\">Gågata</i>). Marks a pedestrian street (gågata). Vehicles may drive at walking speed only, may not park, and must give way to pedestrians. Motor vehicles may only cross it, except for deliveries to shops, transport of goods or residents to and from addresses, transport of hotel guests, and transport of sick or disabled people. A panel can prohibit even that traffic.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E7"],"gen":"sign"},{"id":"sign-E8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E8-1\" alt=\"E8 End of pedestrian street\" width=\"64\" height=\"64\"></div>","opts":["Recommended maximum speed","End of pedestrian street","Environmental zone","Recommended lower speed"],"a":1,"ex":"E8 is <strong>End of pedestrian street</strong> (Swedish: <i lang=\"sv\">Gågata upphör</i>). Marks the end of a pedestrian street. It is left out if it is clear anyway where the street ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E8"],"gen":"sign"},{"id":"sign-E9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E9-1\" alt=\"E9 Walking-speed area\" width=\"64\" height=\"64\"></div>","opts":["Merging lanes (zip merge)","Walking-speed area","Taxi rank","End of motorway"],"a":1,"ex":"E9 is <strong>Walking-speed area</strong> (Swedish: <i lang=\"sv\">Gångfartsområde</i>). Marks a walking-speed area (gångfartsområde). Vehicles may drive at walking speed only, may not park, and must give way to pedestrians.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E9"],"gen":"sign"},{"id":"sign-E10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E10-1\" alt=\"E10 End of walking-speed area\" width=\"64\" height=\"64\"></div>","opts":["Emergency lay-by","End of walking-speed area","Escape route","End of motorway"],"a":1,"ex":"E10 is <strong>End of walking-speed area</strong> (Swedish: <i lang=\"sv\">Gångfartsområde upphör</i>). Marks the end of a walking-speed area. It is left out if it is clear anyway where the area ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E10"],"gen":"sign"},{"id":"sign-E11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E11-1\" alt=\"E11 Recommended lower speed\" width=\"64\" height=\"64\"></div>","opts":["End of expressway","Recommended lower speed","Emergency lay-by","Recommended maximum speed"],"a":1,"ex":"E11 is <strong>Recommended lower speed</strong> (Swedish: <i lang=\"sv\">Rekommenderad lägre hastighet</i>). Marks a stretch or an area where special measures have been taken, or where conditions make it suitable to drive slower than the speed limit. The recommended speed is shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E11"],"gen":"sign"},{"id":"sign-E12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E12-1\" alt=\"E12 End of recommended lower speed\" width=\"64\" height=\"64\"></div>","opts":["Parking","End of recommended lower speed","End of environmental zone","End of motorway"],"a":1,"ex":"E12 is <strong>End of recommended lower speed</strong> (Swedish: <i lang=\"sv\">Rekommenderad lägre hastighet upphör</i>). Marks the end of a stretch with a recommended lower speed. It is left out if it is clear anyway where the stretch ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E12"],"gen":"sign"},{"id":"sign-E13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E13-1\" alt=\"E13 Recommended maximum speed\" width=\"64\" height=\"64\"></div>","opts":["Environmental zone","End of expressway","Recommended maximum speed","End of recommended lower speed"],"a":2,"ex":"E13 is <strong>Recommended maximum speed</strong> (Swedish: <i lang=\"sv\">Rekommenderad högsta hastighet</i>). Used only as a variable (electronic) sign. It shows that conditions are temporarily such that it is not suitable to drive faster than the speed shown, for example because of queues, an accident or bad weather. The speed shown is always lower than the speed limit.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E13"],"gen":"sign"},{"id":"sign-E14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E14-1\" alt=\"E14 End of recommended maximum speed\" width=\"64\" height=\"64\"></div>","opts":["Automatic traffic surveillance","End of recommended maximum speed","End of built-up area","Environmental zone"],"a":1,"ex":"E14 is <strong>End of recommended maximum speed</strong> (Swedish: <i lang=\"sv\">Rekommenderad högsta hastighet upphör</i>). Shows that the temporary conditions behind a recommended maximum speed (E13) have ended. It is left out if that is clear anyway.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E14"],"gen":"sign"},{"id":"sign-E15","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E15-1\" alt=\"E15 Merging lanes (zip merge)\" width=\"64\" height=\"64\"></div>","opts":["End of walking-speed area","Merging lanes (zip merge)","Zone sign","One-way traffic"],"a":1,"ex":"E15 is <strong>Merging lanes (zip merge)</strong> (Swedish: <i lang=\"sv\">Sammanvävning</i>). Informs that two lanes or two carriageways run together and that drivers must adapt to each other (chapter 3, section 44 of the Road Traffic Ordinance). It is also used in advance, with the distance on a panel.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E15"],"gen":"sign"},{"id":"sign-E16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E16-1\" alt=\"E16 One-way traffic\" width=\"64\" height=\"64\"></div>","opts":["Special rules for parking","One-way traffic","End of built-up area","Escape route"],"a":1,"ex":"E16 is <strong>One-way traffic</strong> (Swedish: <i lang=\"sv\">Enkelriktad trafik</i>). Shows that vehicle traffic on the road goes one way only, in the direction of the arrow. An upward arrow means traffic goes one way straight ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E16"],"gen":"sign"},{"id":"sign-E17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E17-1\" alt=\"E17 Dead end\" width=\"64\" height=\"64\"></div>","opts":["End of environmental zone","Dead end","Recommended lower speed","End of built-up area"],"a":1,"ex":"E17 is <strong>Dead end</strong> (Swedish: <i lang=\"sv\">Återvändsväg E17</i>). Shows that you cannot drive through. The symbol is drawn to match the place and can be part of a direction sign. If cyclists and class II moped riders can get through, the bicycle symbol (S8) is added to the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E17"],"gen":"sign"},{"id":"sign-E18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E18-1\" alt=\"E18 Passing place\" width=\"64\" height=\"64\"></div>","opts":["Escape route","End of environmental zone","Passing place","End of built-up area"],"a":2,"ex":"E18 is <strong>Passing place</strong> (Swedish: <i lang=\"sv\">Mötesplats</i>). Marks a passing place (mötesplats) on a narrow road, where vehicles can meet or let others overtake.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E18"],"gen":"sign"},{"id":"sign-E19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E19-1\" alt=\"E19 Parking\" width=\"64\" height=\"64\"></div>","opts":["Special rules for parking","Parking","Toll road or charge","Bus stop"],"a":1,"ex":"E19 is <strong>Parking</strong> (Swedish: <i lang=\"sv\">Parkering</i>). Parking is allowed in a car park, or on a stretch on the side of the road where the sign stands. By a road, the permission starts at the sign and applies as a panel says, until another stopping or parking rule is signed, or else to the next junction. In a car park it covers the whole car park. It does not allow parking where the Road Traffic Ordinance forbids stopping or parking, and it does not allow parking longer than 24 hours in a row on weekdays on public streets and roads.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E19"],"gen":"sign"},{"id":"sign-E20","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E20-1\" alt=\"E20 Zone sign\" width=\"64\" height=\"64\"></div>","opts":["Recommended lower speed","End of expressway","Zone sign","End of motorway"],"a":2,"ex":"E20 is <strong>Zone sign</strong> (Swedish: <i lang=\"sv\">Områdesmärke</i>). Marks the start of an area (zone) where the prohibition or permission shown inside the sign applies. It stands at every entrance to the area and applies until sign E21 (end of zone) or until it is otherwise clear that it no longer applies. Exceptions inside the area are shown with other signs and panels, and the zone rule applies again after them without a new sign. Times can be shown in the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E20"],"gen":"sign"},{"id":"sign-E22","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E22-1\" alt=\"E22 Bus stop\" width=\"64\" height=\"64\"></div>","opts":["End of walking-speed area","Bus stop","End of motorway","End of cycle street"],"a":1,"ex":"E22 is <strong>Bus stop</strong> (Swedish: <i lang=\"sv\">Busshållplats</i>). Marks a stop for buses in scheduled service and school transport, unless the stop is clearly shown in another way. Bus lines, operators and times may be shown on or by the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E22"],"gen":"sign"},{"id":"sign-E23","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E23-1\" alt=\"E23 Taxi rank\" width=\"64\" height=\"64\"></div>","opts":["End of expressway","Taxi rank","End of recommended maximum speed","End of walking-speed area"],"a":1,"ex":"E23 is <strong>Taxi rank</strong> (Swedish: <i lang=\"sv\">Taxi</i>). Marks the far end (in the direction of travel) of a special place where taxis wait.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E23"],"gen":"sign"},{"id":"sign-E24","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E24-1\" alt=\"E24 Automatic traffic surveillance\" width=\"64\" height=\"64\"></div>","opts":["Special rules for parking","Automatic traffic surveillance","Taxi rank","End of expressway"],"a":1,"ex":"E24 is <strong>Automatic traffic surveillance</strong> (Swedish: <i lang=\"sv\">Automatisk trafikövervakning</i>). Shows that automatic monitoring with a camera or similar may take place at the spot or along the stretch – to check traffic rules (for example speed), or for taxes or fees. Personal data may be recorded. For a longer stretch, the length is shown on panel T1, and the sign is repeated at suitable distances.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E24"],"gen":"sign"},{"id":"sign-E25","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E25-1\" alt=\"E25 Toll road or charge\" width=\"64\" height=\"64\"></div>","opts":["End of built-up area","End of expressway","Toll road or charge","Parking"],"a":2,"ex":"E25 is <strong>Toll road or charge</strong> (Swedish: <i lang=\"sv\">Betalväg</i>). Shows that a fee or special tax must be paid to drive on a certain road or within a certain area, for example congestion tax or a bridge toll.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E25"],"gen":"sign"},{"id":"sign-E26","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E26-1\" alt=\"E26 Tunnel\" width=\"64\" height=\"64\"></div>","opts":["Emergency exit","Tunnel","End of environmental zone","Merging lanes (zip merge)"],"a":1,"ex":"E26 is <strong>Tunnel</strong> (Swedish: <i lang=\"sv\">Tunnel</i>). Marks a tunnel. The length of the tunnel is shown, and its name may be shown. The sign is repeated after every kilometre, then showing the remaining length.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E26"],"gen":"sign"},{"id":"sign-E27","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E27-1\" alt=\"E27 Emergency lay-by\" width=\"64\" height=\"64\"></div>","opts":["End of motorway","Escape route","Emergency lay-by","End of built-up area"],"a":2,"ex":"E27 is <strong>Emergency lay-by</strong> (Swedish: <i lang=\"sv\">Nöduppställningsplats</i>). Marks a place to stop a vehicle after a breakdown, engine failure or similar. A symbol for an emergency telephone or a fire extinguisher may be added. With a panel showing distance, it gives advance notice.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E27"],"gen":"sign"},{"id":"sign-E28","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E28-1\" alt=\"E28 Emergency exit\" width=\"64\" height=\"64\"></div>","opts":["Tunnel","Emergency exit","End of built-up area","End of environmental zone"],"a":1,"ex":"E28 is <strong>Emergency exit</strong> (Swedish: <i lang=\"sv\">Nödutgång</i>). Marks an emergency exit for people on foot, for example in a tunnel.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E28"],"gen":"sign"},{"id":"sign-E29","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E29-1\" alt=\"E29 Escape route\" width=\"64\" height=\"64\"></div>","opts":["Built-up area","Escape route","End of expressway","End of motorway"],"a":1,"ex":"E29 is <strong>Escape route</strong> (Swedish: <i lang=\"sv\">Utrymningsväg</i>). Shows the direction and distance to an emergency exit or similar for people on foot. The signs are placed at most 25 metres apart.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E29"],"gen":"sign"},{"id":"sign-E31","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E31-1\" alt=\"E31 Environmental zone\" width=\"64\" height=\"64\"></div>","opts":["End of recommended maximum speed","Environmental zone","Emergency lay-by","Emergency exit"],"a":1,"ex":"E31 is <strong>Environmental zone</strong> (Swedish: <i lang=\"sv\">Miljözon</i>). Marks the start of an environmental zone (miljözon), where only vehicles meeting certain emission standards may be driven (Road Traffic Ordinance, chapter 4, sections 22–24 a). Class 1 covers heavy trucks and buses, class 2 covers cars, light trucks and light buses, and class 3 has the strictest rules for both groups. The zone applies until sign E6 (end of built-up area), E32 (end of zone) or another zone sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E31"],"gen":"sign"},{"id":"sign-E32","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E32-1\" alt=\"E32 End of environmental zone\" width=\"64\" height=\"64\"></div>","opts":["Bus stop","Merging lanes (zip merge)","End of environmental zone","End of motorway"],"a":2,"ex":"E32 is <strong>End of environmental zone</strong> (Swedish: <i lang=\"sv\">Slut på miljözon</i>). Marks the end of an environmental zone.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E32"],"gen":"sign"},{"id":"sign-E33","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E33-CYKELGATA\" alt=\"E33 Cycle street\" width=\"64\" height=\"64\"></div>","opts":["Expressway","Cycle street","Passing place","Parking"],"a":1,"ex":"E33 is <strong>Cycle street</strong> (Swedish: <i lang=\"sv\">Cykelgata</i>). Marks a cycle street (cykelgata). Vehicles may not drive faster than 30 km/h, may only park in specially arranged parking spaces, and drivers of motor vehicles must adapt their speed to the cyclists. A driver who comes onto a cycle street from another road must give way to vehicles on the cycle street.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E33"],"gen":"sign"},{"id":"sign-E34","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E34-CYKELGATA-UPPHOR\" alt=\"E34 End of cycle street\" width=\"64\" height=\"64\"></div>","opts":["Recommended maximum speed","End of cycle street","End of expressway","Taxi rank"],"a":1,"ex":"E34 is <strong>End of cycle street</strong> (Swedish: <i lang=\"sv\">Cykelgata upphör</i>). Marks the end of a cycle street.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E34"],"gen":"sign"},{"id":"sign-M1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M1-1\" alt=\"M1 Centre line or lane line\" width=\"64\" height=\"64\"></div>","opts":["Warning line","Yellow zigzag line","Centre line or lane line","Parking space marking"],"a":2,"ex":"M1 is <strong>Centre line or lane line</strong> (Swedish: <i lang=\"sv\">Mittlinje eller körfältslinje</i>). A broken line. As a centre line it marks the border between lanes for traffic in opposite directions; as a lane line it marks the border between lanes in the same direction. The dashes and gaps have the length ratio 1:3 or 1:1. A centre line can also mark the middle of a cycle track (ratio 1:1).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M1"],"gen":"sign"},{"id":"sign-M2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M2-1\" alt=\"M2 Edge line\" width=\"64\" height=\"64\"></div>","opts":["Purpose place marking","Bicycle symbol","Edge line","Reversible lane line"],"a":2,"ex":"M2 is <strong>Edge line</strong> (Swedish: <i lang=\"sv\">Kantlinje</i>). A broken line marking the outer edge of the carriageway. Ratio 1:2 between dash and gap.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M2"],"gen":"sign"},{"id":"sign-M3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M3-1\" alt=\"M3 Warning line\" width=\"64\" height=\"64\"></div>","opts":["Bicycle symbol","Warning line","Centre line combined with a warning line","Cycle lane line"],"a":1,"ex":"M3 is <strong>Warning line</strong> (Swedish: <i lang=\"sv\">Varningslinje</i>). A broken line with long dashes and short gaps (ratio 3:1) between lanes for opposite directions. It tells you that crossing it is unsuitable because of traffic conditions, for example poor sight ahead. It can also warn of a solid line coming up.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M3"],"gen":"sign"},{"id":"sign-M4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M4-1\" alt=\"M4 Guide line\" width=\"64\" height=\"64\"></div>","opts":["Reversible lane line","Guide line","Cycle lane line","Stop line"],"a":1,"ex":"M4 is <strong>Guide line</strong> (Swedish: <i lang=\"sv\">Ledlinje</i>). A broken line (ratio 1:1) showing a suitable path through complicated junctions, or elsewhere where guidance is needed.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M4"],"gen":"sign"},{"id":"sign-M5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M5-1\" alt=\"M5 Cycle lane line\" width=\"64\" height=\"64\"></div>","opts":["Solid line","Guide line","Cycle lane line","Bicycle symbol"],"a":2,"ex":"M5 is <strong>Cycle lane line</strong> (Swedish: <i lang=\"sv\">Cykelfältslinje</i>). A broken line (ratio 1:1) marking the border between a cycle lane and another lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M5"],"gen":"sign"},{"id":"sign-M6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M6-1\" alt=\"M6 Bus lane line\" width=\"64\" height=\"64\"></div>","opts":["Guide line","Bus lane line","Warning line","No parking (yellow broken line)"],"a":1,"ex":"M6 is <strong>Bus lane line</strong> (Swedish: <i lang=\"sv\">Linje för fordon i linjetrafik med flera</i>). A broken line (ratio 1:1) marking the border between a lane for buses in scheduled service (and others allowed) and another lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M6"],"gen":"sign"},{"id":"sign-M7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M7-1\" alt=\"M7 Reversible lane line\" width=\"64\" height=\"64\"></div>","opts":["Edge line","Reversible lane line","Solid line","Cycle box"],"a":1,"ex":"M7 is <strong>Reversible lane line</strong> (Swedish: <i lang=\"sv\">Reversibelt körfält</i>). A double broken line (ratio 1:1) marking a lane that is used by traffic in one direction at some times and the other direction at other times.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M7"],"gen":"sign"},{"id":"sign-M8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M8-1\" alt=\"M8 Solid line\" width=\"64\" height=\"64\"></div>","opts":["Stop line","Solid line","Give-way or stop ahead","Warning line combined with a solid line"],"a":1,"ex":"M8 is <strong>Solid line</strong> (Swedish: <i lang=\"sv\">Heldragen linje</i>). A solid line replaces a broken line where it is not allowed, for safety reasons, to cross over to oncoming lanes, change lanes or drive out onto the shoulder. You may not drive with any wheel over a solid line (with a few exceptions, for example to pass an obstacle or to reach a property, with special care). A solid centre line can be single or double; a solid lane line and a solid edge line are single.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M8"],"gen":"sign"},{"id":"sign-M9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M9-1\" alt=\"M9 Restricted area (hatched area)\" width=\"64\" height=\"64\"></div>","opts":["Guide line","Restricted area (hatched area)","Warning line combined with a solid line","Purpose place marking"],"a":1,"ex":"M9 is <strong>Restricted area (hatched area)</strong> (Swedish: <i lang=\"sv\">Spärrområde</i>). An area marked with angled or diagonal stripes and bordered by a solid line. Vehicles may not drive on it (Road Traffic Ordinance chapter 3, section 11). Part or all of the area can be painted white.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M9"],"gen":"sign"},{"id":"sign-M10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M10-1\" alt=\"M10 Centre or lane line combined with a solid line\" width=\"64\" height=\"64\"></div>","opts":["Cycle box","Warning line combined with a solid line","Centre or lane line combined with a solid line","Pedestrian symbol"],"a":2,"ex":"M10 is <strong>Centre or lane line combined with a solid line</strong> (Swedish: <i lang=\"sv\">Mittlinje eller körfältslinje och heldragen linje</i>). Used where vehicles on the side of the solid line may not change lanes or cross, while vehicles on the side of the broken line may.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M10"],"gen":"sign"},{"id":"sign-M11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M11-1\" alt=\"M11 Warning line combined with a solid line\" width=\"64\" height=\"64\"></div>","opts":["Cycle box","Warning line combined with a solid line","Pedestrian and cycle arrow","Lane arrows"],"a":1,"ex":"M11 is <strong>Warning line combined with a solid line</strong> (Swedish: <i lang=\"sv\">Varningslinje och heldragen linje</i>). Used where vehicles on the side of the solid line may not change lanes or cross, while vehicles on the warning-line side may (if it is safe).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M11"],"gen":"sign"},{"id":"sign-M12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M12-1\" alt=\"M12 Centre line combined with a warning line\" width=\"64\" height=\"64\"></div>","opts":["Give-way or stop ahead","Centre line combined with a warning line","Give-way line","Edge line"],"a":1,"ex":"M12 is <strong>Centre line combined with a warning line</strong> (Swedish: <i lang=\"sv\">Mittlinje och varningslinje</i>). Used where crossing the warning line is unsuitable because of the traffic conditions, while crossing from the centre-line side is less of a problem.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M12"],"gen":"sign"},{"id":"sign-M13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M13-1\" alt=\"M13 Stop line\" width=\"64\" height=\"64\"></div>","opts":["Warning line","Lane arrows","Stop line","Cycle passage or cycle crossing marking"],"a":2,"ex":"M13 is <strong>Stop line</strong> (Swedish: <i lang=\"sv\">Stopplinje</i>). Marks where a vehicle must stop because of a sign, a traffic signal or a level-crossing light signal (Y1).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M13"],"gen":"sign"},{"id":"sign-M14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M14-1\" alt=\"M14 Give-way line\" width=\"64\" height=\"64\"></div>","opts":["Speed limit marking","Guide line","Give-way line","BUSS marking"],"a":2,"ex":"M14 is <strong>Give-way line</strong> (Swedish: <i lang=\"sv\">Väjningslinje</i>). A row of triangles across the road (“shark’s teeth”) that marks the line vehicles should not pass when giving way.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M14"],"gen":"sign"},{"id":"sign-M15","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M15-1\" alt=\"M15 Pedestrian crossing marking\" width=\"64\" height=\"64\"></div>","opts":["Speed limit marking","Pedestrian crossing marking","Change lanes","Give-way or stop ahead"],"a":1,"ex":"M15 is <strong>Pedestrian crossing marking</strong> (Swedish: <i lang=\"sv\">Övergångsställe</i>). Stripes across the road marking a pedestrian crossing. It is used where sign B3 is placed.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M15"],"gen":"sign"},{"id":"sign-M16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M16-1\" alt=\"M16 Cycle passage or cycle crossing marking\" width=\"64\" height=\"64\"></div>","opts":["Give-way or stop ahead","Cycle passage or cycle crossing marking","Bus lane line","Edge line"],"a":1,"ex":"M16 is <strong>Cycle passage or cycle crossing marking</strong> (Swedish: <i lang=\"sv\">Cykelpassage eller cykelöverfart</i>). Marks a cycle passage or a cycle crossing (where sign B8 stands). At a cycle crossing it is combined with a give-way line (M14). A pedestrian crossing marking may form one of its edges.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M16"],"gen":"sign"},{"id":"sign-M17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M17-1\" alt=\"M17 Speed bump marking\" width=\"64\" height=\"64\"></div>","opts":["Guide line","Speed bump marking","Cycle box","Purpose place marking"],"a":1,"ex":"M17 is <strong>Speed bump marking</strong> (Swedish: <i lang=\"sv\">Farthinder</i>). Marks a speed bump, dip or similar.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M17"],"gen":"sign"},{"id":"sign-M17a","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M17A-CYKELBOX\" alt=\"M17a Cycle box\" width=\"64\" height=\"64\"></div>","opts":["Bicycle symbol","Guide line","Cycle box","Edge line"],"a":2,"ex":"M17a is <strong>Cycle box</strong> (Swedish: <i lang=\"sv\">Cykelbox</i>). Marks a suitable waiting position for cyclists and class II moped riders, for example in front of cars at traffic lights. It is adapted to the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M17a"],"gen":"sign"},{"id":"sign-M18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M18-1\" alt=\"M18 Give-way or stop ahead\" width=\"64\" height=\"64\"></div>","opts":["Parking space marking","Give-way or stop ahead","BUSS marking","Road number marking"],"a":1,"ex":"M18 is <strong>Give-way or stop ahead</strong> (Swedish: <i lang=\"sv\">Förberedande upplysning om väjningsplikt eller stopplikt</i>). A triangle painted on the road warning that you will have to give way or stop further ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M18"],"gen":"sign"},{"id":"sign-M19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M19-1\" alt=\"M19 Lane arrows\" width=\"64\" height=\"64\"></div>","opts":["Bus lane line","Lane arrows","Cycle box","Restricted area (hatched area)"],"a":1,"ex":"M19 is <strong>Lane arrows</strong> (Swedish: <i lang=\"sv\">Körfältspilar</i>). Show the suitable lane for the next junction. If the lane is bordered by solid lane lines, drivers must follow the direction or directions of the arrows (except when entering or leaving a reserved lane near the junction). Double arrows in the same direction show the lane for the next junction and the one after. The arrows also mean you may not drive in the opposite direction.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M19"],"gen":"sign"},{"id":"sign-M20","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M20-1\" alt=\"M20 Change lanes\" width=\"64\" height=\"64\"></div>","opts":["Pedestrian symbol","Change lanes","Speed limit marking","Edge line"],"a":1,"ex":"M20 is <strong>Change lanes</strong> (Swedish: <i lang=\"sv\">Körfältsbyte</i>). An arrow showing that you must change lane as soon as possible, because your lane ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M20"],"gen":"sign"},{"id":"sign-M21","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M21-1\" alt=\"M21 No stopping or parking (yellow line)\" width=\"64\" height=\"64\"></div>","opts":["Yellow zigzag line","Speed limit marking","No stopping or parking (yellow line)","Warning line combined with a solid line"],"a":2,"ex":"M21 is <strong>No stopping or parking (yellow line)</strong> (Swedish: <i lang=\"sv\">Förbud mot att stanna och parkera</i>). A solid yellow line at the edge of the carriageway showing that stopping and parking are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M21"],"gen":"sign"},{"id":"sign-M22","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M22-1\" alt=\"M22 No parking (yellow broken line)\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking marking","No parking (yellow broken line)","Cycle box","Bicycle symbol"],"a":1,"ex":"M22 is <strong>No parking (yellow broken line)</strong> (Swedish: <i lang=\"sv\">Förbud mot att parkera</i>). A broken yellow line at the edge of the carriageway showing that parking is prohibited. It is also used to show the extent of a bus stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M22"],"gen":"sign"},{"id":"sign-M23","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M23-1\" alt=\"M23 Yellow zigzag line\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking marking","Warning line","Yellow zigzag line","Change lanes"],"a":2,"ex":"M23 is <strong>Yellow zigzag line</strong> (Swedish: <i lang=\"sv\">Förbud mot att stanna och parkera eller att parkera</i>). A yellow zigzag that reinforces markings M21 (no stopping or parking) and M22 (no parking).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M23"],"gen":"sign"},{"id":"sign-M24","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M24-1\" alt=\"M24 Parking space marking\" width=\"64\" height=\"64\"></div>","opts":["Guide line","Parking space marking","No parking (yellow broken line)","Bus lane line"],"a":1,"ex":"M24 is <strong>Parking space marking</strong> (Swedish: <i lang=\"sv\">Uppställningsplats</i>). Marks the border of a space where vehicles may be placed. It can be a broken line.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M24"],"gen":"sign"},{"id":"sign-M25","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M25-1\" alt=\"M25 Pedestrian and cycle arrow\" width=\"64\" height=\"64\"></div>","opts":["BUSS marking","Guide line","Pedestrian and cycle arrow","Warning line"],"a":2,"ex":"M25 is <strong>Pedestrian and cycle arrow</strong> (Swedish: <i lang=\"sv\">Gång- och cykelpil</i>). Shows a suitable route for pedestrians or for cyclists and class II moped riders.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M25"],"gen":"sign"},{"id":"sign-M26","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M26-1\" alt=\"M26 Bicycle symbol\" width=\"64\" height=\"64\"></div>","opts":["Reversible lane line","Bicycle symbol","Disabled parking marking","Give-way line"],"a":1,"ex":"M26 is <strong>Bicycle symbol</strong> (Swedish: <i lang=\"sv\">Cykel</i>). Shows a track or a suitable route for cyclists and class II moped riders.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M26"],"gen":"sign"},{"id":"sign-M27","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M27-1\" alt=\"M27 Pedestrian symbol\" width=\"64\" height=\"64\"></div>","opts":["Cycle passage or cycle crossing marking","Pedestrian symbol","No parking (yellow broken line)","Parking space marking"],"a":1,"ex":"M27 is <strong>Pedestrian symbol</strong> (Swedish: <i lang=\"sv\">Gående</i>). Shows a path or suitable route for pedestrians.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M27"],"gen":"sign"},{"id":"sign-M28","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M28-1\" alt=\"M28 BUSS marking\" width=\"64\" height=\"64\"></div>","opts":["Speed bump marking","Speed limit marking","BUSS marking","Pedestrian crossing marking"],"a":2,"ex":"M28 is <strong>BUSS marking</strong> (Swedish: <i lang=\"sv\">Buss</i>). Shows that the lane is meant for buses in scheduled service and others allowed there.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M28"],"gen":"sign"},{"id":"sign-M29","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M29-1\" alt=\"M29 Speed limit marking\" width=\"64\" height=\"64\"></div>","opts":["Guide line","Parking space marking","Speed limit marking","Pedestrian and cycle arrow"],"a":2,"ex":"M29 is <strong>Speed limit marking</strong> (Swedish: <i lang=\"sv\">Hastighet</i>). Painted on the road to remind you of the speed limit.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M29"],"gen":"sign"},{"id":"sign-M30","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M30\" alt=\"M30 Road number marking\" width=\"64\" height=\"64\"></div>","opts":["No parking (yellow broken line)","Road number marking","Bus lane line","Pedestrian crossing marking"],"a":1,"ex":"M30 is <strong>Road number marking</strong> (Swedish: <i lang=\"sv\">Vägnummer</i>). Shows the road number painted on the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M30"],"gen":"sign"},{"id":"sign-M31","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M31-1\" alt=\"M31 Purpose place marking\" width=\"64\" height=\"64\"></div>","opts":["Bicycle symbol","Purpose place marking","Stop line","Information marking"],"a":1,"ex":"M31 is <strong>Purpose place marking</strong> (Swedish: <i lang=\"sv\">Ändamålsplats</i>). Shows that a parking space is meant for a certain purpose, for example LASTPLATS (loading place). The text matches the purpose.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M31"],"gen":"sign"},{"id":"sign-M32","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M32-1\" alt=\"M32 STOPP marking\" width=\"64\" height=\"64\"></div>","opts":["Edge line","Warning line combined with a solid line","STOPP marking","Give-way line"],"a":2,"ex":"M32 is <strong>STOPP marking</strong> (Swedish: <i lang=\"sv\">Stopp</i>). The word STOPP painted on the road. Used together with sign B2 to reinforce the duty to stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M32"],"gen":"sign"},{"id":"sign-M33","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M33-1\" alt=\"M33 Disabled parking marking\" width=\"64\" height=\"64\"></div>","opts":["Parking space marking","Disabled parking marking","Guide line","Reversible lane line"],"a":1,"ex":"M33 is <strong>Disabled parking marking</strong> (Swedish: <i lang=\"sv\">Rörelsehindrad</i>). Shows a parking space only for people with reduced mobility (with a disabled parking permit).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M33"],"gen":"sign"},{"id":"sign-M34","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M34-1\" alt=\"M34 Information marking\" width=\"64\" height=\"64\"></div>","opts":["Cycle box","Information marking","Guide line","Warning line combined with a solid line"],"a":1,"ex":"M34 is <strong>Information marking</strong> (Swedish: <i lang=\"sv\">Information</i>). Text painted on the road that gives information, a warning or guidance that matters to road users, for example SKOLA (school).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M34"],"gen":"sign"},{"id":"sign-P1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P1-1\" alt=\"P1 Police – stop (arm stretched out)\" width=\"64\" height=\"64\"></div>","opts":["Police vehicle – slow down (traffic behind)","Police – stop (arm stretched out)","Control point","Police – stop (lamp)"],"a":1,"ex":"P1 is <strong>Police – stop (arm stretched out)</strong> (Swedish: <i lang=\"sv\">Stopp</i>). Stop for road users coming from in front of or behind the police officer. It is used in junctions and applies as long as the officer faces the same way. For road users coming from the side, it means the way is clear and they may drive. It can be combined with P2 and given with a stop paddle.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P1"],"gen":"sign"},{"id":"sign-P2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P2-1\" alt=\"P2 Police – stop (raised hand)\" width=\"64\" height=\"64\"></div>","opts":["Police – stop (lamp)","Police vehicle – pull over and stop in front","Police – stop (raised hand)","Police vehicle – slow down (traffic behind)"],"a":2,"ex":"P2 is <strong>Police – stop (raised hand)</strong> (Swedish: <i lang=\"sv\">Stopp</i>). Stop for the road user that the palm of the hand is facing. It can be given with a stop paddle.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P2"],"gen":"sign"},{"id":"sign-P3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P3-1\" alt=\"P3 Police – stop (lamp)\" width=\"64\" height=\"64\"></div>","opts":["Control point ahead","Police – stop (lamp)","Control point","Police vehicle – follow and stop behind it"],"a":1,"ex":"P3 is <strong>Police – stop (lamp)</strong> (Swedish: <i lang=\"sv\">Stopp</i>). Stop for the road user that the lamp is facing. Used in darkness and when visibility is poor; the lamp is held where it is easiest to see.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P3"],"gen":"sign"},{"id":"sign-P4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P4-1\" alt=\"P4 Police – drive on\" width=\"64\" height=\"64\"></div>","opts":["Police – stop (lamp)","Police – drive on","Police – slow down","Police – stop (raised hand)"],"a":1,"ex":"P4 is <strong>Police – drive on</strong> (Swedish: <i lang=\"sv\">Kör fram</i>). Road users in the direction of the officer’s waving movement may continue.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P4"],"gen":"sign"},{"id":"sign-P5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P5-1\" alt=\"P5 Police – slow down\" width=\"64\" height=\"64\"></div>","opts":["Police – drive on","Police – stop (lamp)","Police – slow down","Police – stop (raised hand)"],"a":2,"ex":"P5 is <strong>Police – slow down</strong> (Swedish: <i lang=\"sv\">Minska hastigheten</i>). The road user the officer is facing must reduce speed. In darkness or poor visibility it can be made clearer with a lamp or reflector showing white or yellow light.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P5"],"gen":"sign"},{"id":"sign-P6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P6-1\" alt=\"P6 Control point\" width=\"64\" height=\"64\"></div>","opts":["Police – stop (raised hand)","Police vehicle – slow down (traffic behind)","Control point","Control point ahead"],"a":2,"ex":"P6 is <strong>Control point</strong> (Swedish: <i lang=\"sv\">Kontroll</i>). Drivers must drive into the control point to be checked. If a symbol for a vehicle type is shown, only drivers of those vehicles must drive in.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P6"],"gen":"sign"},{"id":"sign-P7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P7-1\" alt=\"P7 Control point ahead\" width=\"64\" height=\"64\"></div>","opts":["Police – stop (lamp)","Control point ahead","Control point","Police – stop (raised hand)"],"a":1,"ex":"P7 is <strong>Control point ahead</strong> (Swedish: <i lang=\"sv\">Förberedande upplysning om kontroll</i>). Advance notice of a control point.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P7"],"gen":"sign"},{"id":"sign-P8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P8-1\" alt=\"P8 Police vehicle – slow down (traffic behind)\" width=\"64\" height=\"64\"></div>","opts":["Police vehicle – follow and stop behind it","Police – drive on","Police vehicle – slow down (traffic behind)","Police – stop (raised hand)"],"a":2,"ex":"P8 is <strong>Police vehicle – slow down (traffic behind)</strong> (Swedish: <i lang=\"sv\">Minska hastigheten</i>). Road users behind the police vehicle must reduce speed. In darkness it can be made clearer with white or yellow light or a reflector.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P8"],"gen":"sign"},{"id":"sign-P9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P9-1\" alt=\"P9 Police vehicle – slow down (oncoming traffic)\" width=\"64\" height=\"64\"></div>","opts":["Police vehicle – pull over and stop in front","Police vehicle – slow down (oncoming traffic)","Police – stop (lamp)","Control point ahead"],"a":1,"ex":"P9 is <strong>Police vehicle – slow down (oncoming traffic)</strong> (Swedish: <i lang=\"sv\">Minska hastigheten</i>). Road users meeting the police vehicle must reduce speed. In darkness it can be made clearer with white or yellow light or a reflector.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P9"],"gen":"sign"},{"id":"sign-P10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P10-1\" alt=\"P10 Police vehicle – follow and stop behind it\" width=\"64\" height=\"64\"></div>","opts":["Police – stop (lamp)","Police – drive on","Police vehicle – follow and stop behind it","Police – stop (raised hand)"],"a":2,"ex":"P10 is <strong>Police vehicle – follow and stop behind it</strong> (Swedish: <i lang=\"sv\">Följ efter och stanna bakom polisfordonet när detta stannar</i>). The driver of the vehicle behind the police vehicle must follow it and stop when it stops. It can be given with a stop paddle.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P10"],"gen":"sign"},{"id":"sign-P11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P11-1\" alt=\"P11 Police vehicle – pull over and stop in front\" width=\"64\" height=\"64\"></div>","opts":["Police – slow down","Police vehicle – slow down (oncoming traffic)","Police vehicle – pull over and stop in front","Police – stop (raised hand)"],"a":2,"ex":"P11 is <strong>Police vehicle – pull over and stop in front</strong> (Swedish: <i lang=\"sv\">Kör in till vägkanten och stanna framför polisfordonet</i>). The driver of the vehicle in front of the police vehicle must pull over to the side of the road and stop. The signal is given with blue and red lights flashing alternately.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P11"],"gen":"sign"},{"id":"sign-T1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T1-1\" alt=\"T1 Length of stretch\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking permit","Length of stretch","Fee","How the roads continue in the junction"],"a":1,"ex":"T1 is <strong>Length of stretch</strong> (Swedish: <i lang=\"sv\">Vägsträckas längd</i>). Shows where a stretch begins and ends, measured from the sign. For example “200–800 m” means the sign above applies from 200 metres ahead to 800 metres ahead; “0–1.2 km” means it applies from here for 1.2 kilometres.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T1"],"gen":"sign"},{"id":"sign-T2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T2-1\" alt=\"T2 Distance\" width=\"64\" height=\"64\"></div>","opts":["All-way give way","Total weight","Distance","Distance to stop sign"],"a":2,"ex":"T2 is <strong>Distance</strong> (Swedish: <i lang=\"sv\">Avstånd</i>). Shows the distance to what the sign above refers to – for example to a danger, a ban or a give-way point.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T2"],"gen":"sign"},{"id":"sign-T3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T3-1\" alt=\"T3 Distance to stop sign\" width=\"64\" height=\"64\"></div>","opts":["Distance","Extent","Distance to stop sign","Text panel"],"a":2,"ex":"T3 is <strong>Distance to stop sign</strong> (Swedish: <i lang=\"sv\">Avstånd till stopplikt</i>). Used only under sign B1 (give way). It warns that there is a stop sign (stopplikt) at the distance shown.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T3"],"gen":"sign"},{"id":"sign-T4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T4-1\" alt=\"T4 Free width\" width=\"64\" height=\"64\"></div>","opts":["Parking ticket","All-way give way","Free width","Disabled parking permit"],"a":2,"ex":"T4 is <strong>Free width</strong> (Swedish: <i lang=\"sv\">Fri bredd</i>). Shows the free width of the road, for example where the road narrows.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T4"],"gen":"sign"},{"id":"sign-T5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T5\" alt=\"T5 Total weight\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking permit","Total weight","Distance","Tunnel category"],"a":1,"ex":"T5 is <strong>Total weight</strong> (Swedish: <i lang=\"sv\">Totalvikt</i>). The sign above applies only to vehicles with a total weight (the highest weight the vehicle is registered for) above the value shown.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T5"],"gen":"sign"},{"id":"sign-T6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T6-1\" alt=\"T6 Times\" width=\"64\" height=\"64\"></div>","opts":["Extent","Times","Free width","Time limit for parking"],"a":1,"ex":"T6 is <strong>Times</strong> (Swedish: <i lang=\"sv\">Tidsangivelse</i>). Shows when the sign above applies. Black or white numbers without brackets mean weekdays except the day before a Sunday or public holiday. Numbers in brackets mean the day before a Sunday or public holiday (usually Saturday). Red numbers mean Sundays and public holidays. If a period runs past midnight, the part after midnight belongs to the next day. If a particular date or weekday is given, the rule applies that day whatever kind of day it is.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T6"],"gen":"sign"},{"id":"sign-T7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T7\" alt=\"T7 Disabled parking permit\" width=\"64\" height=\"64\"></div>","opts":["Free width","Disabled parking permit","Extent","All-way stop"],"a":1,"ex":"T7 is <strong>Disabled parking permit</strong> (Swedish: <i lang=\"sv\">Rörelsehindrade</i>). Used only under sign E19 (parking). The parking applies to people who may park with a parking permit for people with disabilities. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T7"],"gen":"sign"},{"id":"sign-T8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T8-1\" alt=\"T8 Vehicle type or road user panel\" width=\"64\" height=\"64\"></div>","opts":["Free width","Times","Vehicle type or road user panel","All-way stop"],"a":2,"ex":"T8 is <strong>Vehicle type or road user panel</strong> (Swedish: <i lang=\"sv\">Symboltavla</i>). The sign above applies only to the vehicle type or road user group shown by the symbol. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T8"],"gen":"sign"},{"id":"sign-T9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T9-1\" alt=\"T9 People with impaired sight\" width=\"64\" height=\"64\"></div>","opts":["Times","People with impaired sight","Disabled parking permit","Free width"],"a":1,"ex":"T9 is <strong>People with impaired sight</strong> (Swedish: <i lang=\"sv\">Nedsatt syn</i>). Shows that people with impaired sight are often found here.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T9"],"gen":"sign"},{"id":"sign-T10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T10\" alt=\"T10 People with impaired hearing\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking permit","People with impaired hearing","Free width","All-way stop"],"a":1,"ex":"T10 is <strong>People with impaired hearing</strong> (Swedish: <i lang=\"sv\">Nedsatt hörsel</i>). Shows that people with impaired hearing are often found here. This panel is always yellow.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T10"],"gen":"sign"},{"id":"sign-T11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T11-1\" alt=\"T11 Extent\" width=\"64\" height=\"64\"></div>","opts":["Free width","Extent","Times","Total weight"],"a":1,"ex":"T11 is <strong>Extent</strong> (Swedish: <i lang=\"sv\">Utsträckning</i>). A panel with arrows pointing both ways (horizontal or vertical) means the rule applies on both sides of the sign. An arrow pointing down means the rule ends here. An arrow to the right or left shows that the rule applies in that direction. Under a parking sign (E19) it has black arrows on white without a border.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T11"],"gen":"sign"},{"id":"sign-T12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T12-1\" alt=\"T12 Direction\" width=\"64\" height=\"64\"></div>","opts":["Distance","Direction","People with impaired hearing","Times"],"a":1,"ex":"T12 is <strong>Direction</strong> (Swedish: <i lang=\"sv\">Riktning</i>). Shows the direction to what the sign above refers to.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T12"],"gen":"sign"},{"id":"sign-T13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T13-1\" alt=\"T13 All-way give way\" width=\"64\" height=\"64\"></div>","opts":["How the roads continue in the junction","All-way give way","How to park","Text panel"],"a":1,"ex":"T13 is <strong>All-way give way</strong> (Swedish: <i lang=\"sv\">Flervägsväjning</i>). Shows that drivers on every road into the junction have to give way.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T13"],"gen":"sign"},{"id":"sign-T14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T14-1\" alt=\"T14 All-way stop\" width=\"64\" height=\"64\"></div>","opts":["Free width","All-way stop","How the roads continue in the junction","All-way give way"],"a":1,"ex":"T14 is <strong>All-way stop</strong> (Swedish: <i lang=\"sv\">Flervägsstopp</i>). Shows that drivers on every road into the junction must stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T14"],"gen":"sign"},{"id":"sign-T15","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T15-1\" alt=\"T15 How the roads continue in the junction\" width=\"64\" height=\"64\"></div>","opts":["Times","Fee","How the roads continue in the junction","Direction"],"a":2,"ex":"T15 is <strong>How the roads continue in the junction</strong> (Swedish: <i lang=\"sv\">Vägars fortsättning i korsning</i>). Shows a junction where drivers on the road drawn with a narrow line must give way to vehicles on the road drawn with a wide line. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T15"],"gen":"sign"},{"id":"sign-T16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T16\" alt=\"T16 Fee\" width=\"64\" height=\"64\"></div>","opts":["Free width","Fee","All-way give way","Distance"],"a":1,"ex":"T16 is <strong>Fee</strong> (Swedish: <i lang=\"sv\">Avgift</i>). Parking costs money according to the price list on the parking meter, ticket machine or similar, and any other conditions written there must be followed. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T16"],"gen":"sign"},{"id":"sign-T17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T17-1\" alt=\"T17 Parking disc\" width=\"64\" height=\"64\"></div>","opts":["How to park","Parking disc","All-way stop","Charging place"],"a":1,"ex":"T17 is <strong>Parking disc</strong> (Swedish: <i lang=\"sv\">Parkeringsskiva</i>). You must show the time you started parking with a parking disc (P-skiva) or similar. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T17"],"gen":"sign"},{"id":"sign-T18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T18\" alt=\"T18 Time limit for parking\" width=\"64\" height=\"64\"></div>","opts":["Times","Time limit for parking","Parking disc","Distance"],"a":1,"ex":"T18 is <strong>Time limit for parking</strong> (Swedish: <i lang=\"sv\">Tillåten tid för parkering</i>). Shows the longest time you may park. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T18"],"gen":"sign"},{"id":"sign-T19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T19\" alt=\"T19 Residents\" width=\"64\" height=\"64\"></div>","opts":["Text panel","Disabled parking permit","Residents","Parking disc"],"a":2,"ex":"T19 is <strong>Residents</strong> (Swedish: <i lang=\"sv\">Boende</i>). Residents of an area who have a special permit may park under special conditions. An area code may be added. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T19"],"gen":"sign"},{"id":"sign-T20","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T20\" alt=\"T20 Parking ticket\" width=\"64\" height=\"64\"></div>","opts":["Parking disc","Parking ticket","Distance to stop sign","Text panel"],"a":1,"ex":"T20 is <strong>Parking ticket</strong> (Swedish: <i lang=\"sv\">Parkeringsbiljett</i>). Parking is free of charge, but you must use a parking ticket. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T20"],"gen":"sign"},{"id":"sign-T21","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T21-1\" alt=\"T21 How to park\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking permit","Free width","How to park","Parking ticket"],"a":2,"ex":"T21 is <strong>How to park</strong> (Swedish: <i lang=\"sv\">Uppställning av fordon</i>). Shows how vehicles must be placed in a car park – for example at right angles, in a line, or at an angle. The panel is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T21"],"gen":"sign"},{"id":"sign-T22","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T22-1\" alt=\"T22 Text panel\" width=\"64\" height=\"64\"></div>","opts":["Free width","Text panel","Distance","Disabled parking permit"],"a":1,"ex":"T22 is <strong>Text panel</strong> (Swedish: <i lang=\"sv\">Text</i>). Gives an extra instruction in words that no other panel, or combination of panels, can give. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T22"],"gen":"sign"},{"id":"sign-T24","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T24-1\" alt=\"T24 Charging place\" width=\"64\" height=\"64\"></div>","opts":["Distance to stop sign","Charging place","Distance","All-way stop"],"a":1,"ex":"T24 is <strong>Charging place</strong> (Swedish: <i lang=\"sv\">Laddplats</i>). Used under sign E19 (parking). It marks a place for charging electric vehicles, where only vehicles that can be charged from an external source may park.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T24"],"gen":"sign"},{"id":"sign-SIG1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG1-1\" alt=\"SIG1 Red light\" width=\"64\" height=\"64\"></div>","opts":["Lane signal – red cross","Red light","Lane signal – yellow arrow","Green light"],"a":1,"ex":"SIG1 is <strong>Red light</strong> (Swedish: <i lang=\"sv\">Röd</i>). Stop. Vehicles may not pass the stop line, or the signal if there is no stop line. A red arrow outline in the lamp means the red light only applies to the direction of the arrow.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG1"],"gen":"sign"},{"id":"sign-SIG2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG2-1\" alt=\"SIG2 Red and yellow light\" width=\"64\" height=\"64\"></div>","opts":["Lane signal – green arrow","Public transport signal with a horizontal bar","Red and yellow light","Flashing yellow light"],"a":2,"ex":"SIG2 is <strong>Red and yellow light</strong> (Swedish: <i lang=\"sv\">Röd + gul</i>). The light is about to turn green. Otherwise it means the same as red – you may not drive yet.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG2"],"gen":"sign"},{"id":"sign-SIG3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG3-1\" alt=\"SIG3 Green light\" width=\"64\" height=\"64\"></div>","opts":["Lane signal – red cross","Green light","Yellow light","Public transport signal with a horizontal bar"],"a":1,"ex":"SIG3 is <strong>Green light</strong> (Swedish: <i lang=\"sv\">Grön</i>). Vehicles may go ahead. A green arrow means the signal applies to the direction of the arrow, and you may drive in that direction even if another light is showing at the same time.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG3"],"gen":"sign"},{"id":"sign-SIG4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG4-1\" alt=\"SIG4 Yellow light\" width=\"64\" height=\"64\"></div>","opts":["Green light","Yellow light","Flashing yellow light","Public transport signal with a vertical bar or arrow"],"a":1,"ex":"SIG4 is <strong>Yellow light</strong> (Swedish: <i lang=\"sv\">Gul</i>). Stop. Vehicles may not pass the stop line (or the signal) unless they were so close when the light changed from green to yellow that they cannot stop safely.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG4"],"gen":"sign"},{"id":"sign-SIG5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG5-1\" alt=\"SIG5 Flashing yellow light\" width=\"64\" height=\"64\"></div>","opts":["Red and yellow light","Steady red light (road closed)","Flashing yellow light","Green pedestrian light"],"a":2,"ex":"SIG5 is <strong>Flashing yellow light</strong> (Swedish: <i lang=\"sv\">Blinkande gul</i>). Take special care when passing. It is shown only when the signals are out of order or temporarily not working for a short time; the normal priority rules and signs then apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG5"],"gen":"sign"},{"id":"sign-SIG6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG6-1\" alt=\"SIG6 Red pedestrian light\" width=\"64\" height=\"64\"></div>","opts":["Public transport signal with a horizontal bar","Yellow light","Red pedestrian light","Public transport signal &quot;S&quot;"],"a":2,"ex":"SIG6 is <strong>Red pedestrian light</strong> (Swedish: <i lang=\"sv\">Röd akustisk signal med långsam pulsfrekvens</i>). A standing figure, often with a slow ticking sound. Pedestrians may not step onto the carriageway, cycle track or crossing. Someone already on the road when it turns red should continue to the other side, or stop on a refuge if there is one.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG6"],"gen":"sign"},{"id":"sign-SIG7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG7-1\" alt=\"SIG7 Green pedestrian light\" width=\"64\" height=\"64\"></div>","opts":["Lane signal – red cross","Green pedestrian light","Steady red light (road closed)","Red and yellow light"],"a":1,"ex":"SIG7 is <strong>Green pedestrian light</strong> (Swedish: <i lang=\"sv\">Grön akustisk signal med snabb pulsfrekvens</i>). A walking figure, often with a fast ticking sound. Pedestrians may cross. A flashing green figure (with a fast sound with breaks) means it will soon turn red.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG7"],"gen":"sign"},{"id":"sign-SIG8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG8-1\" alt=\"SIG8 Public transport signal &quot;S&quot;\" width=\"64\" height=\"64\"></div>","opts":["Red and yellow light","Public transport signal &quot;S&quot;","Red pedestrian light","Flashing red lights (bridge, fire station, tunnel …)"],"a":1,"ex":"SIG8 is <strong>Public transport signal &quot;S&quot;</strong> (Swedish: <i lang=\"sv\">S</i>). Stop. A white S in a signal for buses and trams. It applies to vehicles in scheduled service and trams – and to everyone using a bus lane where the signal stands by that lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG8"],"gen":"sign"},{"id":"sign-SIG9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG9-1\" alt=\"SIG9 Public transport signal &quot;S&quot; with a horizontal bar\" width=\"64\" height=\"64\"></div>","opts":["Lane signal – red cross","Yellow light","Public transport signal &quot;S&quot; with a horizontal bar","Red pedestrian light"],"a":2,"ex":"SIG9 is <strong>Public transport signal &quot;S&quot; with a horizontal bar</strong> (Swedish: <i lang=\"sv\">S+vågrätt streck</i>). The signal is about to show the vertical bar (go). Otherwise it means the same as S – stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG9"],"gen":"sign"},{"id":"sign-SIG10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG10-1\" alt=\"SIG10 Public transport signal with a vertical bar or arrow\" width=\"64\" height=\"64\"></div>","opts":["Yellow light","Public transport signal with a vertical bar or arrow","Flashing red lights (bridge, fire station, tunnel …)","Public transport signal &quot;S&quot; with a horizontal bar"],"a":1,"ex":"SIG10 is <strong>Public transport signal with a vertical bar or arrow</strong> (Swedish: <i lang=\"sv\">Lodrätt streck eller pil</i>). Go. Buses and trams may continue. An arrow means it applies to that direction.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG10"],"gen":"sign"},{"id":"sign-SIG11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG11-1\" alt=\"SIG11 Public transport signal with a horizontal bar\" width=\"64\" height=\"64\"></div>","opts":["Flashing yellow light (take special care)","Public transport signal with a horizontal bar","Green pedestrian light","Red and yellow light"],"a":1,"ex":"SIG11 is <strong>Public transport signal with a horizontal bar</strong> (Swedish: <i lang=\"sv\">Vågrätt streck</i>). Stop, unless the vehicle was so close when the signal changed from a vertical to a horizontal bar that it cannot stop safely. A flashing horizontal bar means take special care.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG11"],"gen":"sign"},{"id":"sign-SIG12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG12-1\" alt=\"SIG12 Lane signal – red cross\" width=\"64\" height=\"64\"></div>","opts":["Yellow light","Lane signal – red cross","Steady red light (road closed)","Red pedestrian light"],"a":1,"ex":"SIG12 is <strong>Lane signal – red cross</strong> (Swedish: <i lang=\"sv\">Rött kryss</i>). A red cross above a lane means the lane, and the shoulder next to it, may not be used.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG12"],"gen":"sign"},{"id":"sign-SIG13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG13-1\" alt=\"SIG13 Lane signal – yellow arrow\" width=\"64\" height=\"64\"></div>","opts":["Green pedestrian light","Public transport signal with a vertical bar or arrow","Lane signal – yellow arrow","Red and yellow light"],"a":2,"ex":"SIG13 is <strong>Lane signal – yellow arrow</strong> (Swedish: <i lang=\"sv\">Gul pil eller pilar</i>). A yellow diagonal arrow (or arrows) above a lane means you must change to another lane in the direction shown.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG13"],"gen":"sign"},{"id":"sign-SIG14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG14-1\" alt=\"SIG14 Lane signal – green arrow\" width=\"64\" height=\"64\"></div>","opts":["Yellow light","Red pedestrian light","Lane signal – green arrow","Flashing red lights (bridge, fire station, tunnel …)"],"a":2,"ex":"SIG14 is <strong>Lane signal – green arrow</strong> (Swedish: <i lang=\"sv\">Grön pil</i>). A green arrow pointing down above a lane means the lane may be used. A road sign may be shown instead of the green arrow.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG14"],"gen":"sign"},{"id":"sign-SIG16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG16-1\" alt=\"SIG16 Flashing red lights (bridge, fire station, tunnel …)\" width=\"64\" height=\"64\"></div>","opts":["Public transport signal with a vertical bar or arrow","Flashing red lights (bridge, fire station, tunnel …)","Yellow light","Green light"],"a":1,"ex":"SIG16 is <strong>Flashing red lights (bridge, fire station, tunnel …)</strong> (Swedish: <i lang=\"sv\">Rött blinkande ljus</i>). Two red lights flashing alternately mean stop. You may not pass the stop line, or the signal. They are used where a road is temporarily closed, for example at an opening bridge, a fire or ambulance station, an airfield, road works or a tunnel. A ringing sound may be added.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG16"],"gen":"sign"},{"id":"sign-SIG17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG17-1\" alt=\"SIG17 Steady red light (road closed)\" width=\"64\" height=\"64\"></div>","opts":["Public transport signal with a horizontal bar","Steady red light (road closed)","Yellow light","Lane signal – red cross"],"a":1,"ex":"SIG17 is <strong>Steady red light (road closed)</strong> (Swedish: <i lang=\"sv\">Rött fast ljus</i>). A steady red light means the road is completely closed.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG17"],"gen":"sign"},{"id":"sign-SIG18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG18-1\" alt=\"SIG18 Flashing yellow light (take special care)\" width=\"64\" height=\"64\"></div>","opts":["Yellow light","Flashing red lights (bridge, fire station, tunnel …)","Flashing yellow light (take special care)","Red and yellow light"],"a":2,"ex":"SIG18 is <strong>Flashing yellow light (take special care)</strong> (Swedish: <i lang=\"sv\">Gult blinkande ljus för påkallande av särskild försiktighet</i>). Used where a road is partly closed, or to make a sign or other device easier to notice. It can also be combined with a sound to warn pedestrians of a crossing tram or bus.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG18"],"gen":"sign"},{"id":"sign-X1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X1\" alt=\"X1 Marker arrow\" width=\"64\" height=\"64\"></div>","opts":["Exit marker","Yellow light arrow(s)","Marker arrow","Side obstacle marker"],"a":2,"ex":"X1 is <strong>Marker arrow</strong> (Swedish: <i lang=\"sv\">Markeringspil</i>). Yellow arrow(s) showing that drivers must turn sharply in the direction of the arrow(s), for example because of a bend. The number of arrows matches the place. At road works or other temporary places it has a red background.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X1"],"gen":"sign"},{"id":"sign-X2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X2-1\" alt=\"X2 Obstacle marker board\" width=\"64\" height=\"64\"></div>","opts":["Side obstacle marker","Special warning device","Obstacle marker board","Road barrier"],"a":2,"ex":"X2 is <strong>Obstacle marker board</strong> (Swedish: <i lang=\"sv\">Markeringsskärm för hinder</i>). Shows that the road is narrowed by an obstacle. It can also show that a road is completely or partly closed. The number of yellow fields matches the obstacle. At road works or other temporary places it has a red background.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X2"],"gen":"sign"},{"id":"sign-X3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X3-1\" alt=\"X3 Side obstacle marker\" width=\"64\" height=\"64\"></div>","opts":["Obstacle marker board","Yellow light arrow(s)","Side obstacle marker","Exit marker"],"a":2,"ex":"X3 is <strong>Side obstacle marker</strong> (Swedish: <i lang=\"sv\">Markeringsskärm för sidohinder, farthinder med mera</i>). Marks the edge of a road or carriageway, or separates the directions of traffic at complicated places. Vehicles must pass on the side the yellow stripes slope down towards. At road works or other temporary places it has a red background; the yellow fields may then be horizontal, and you may pass on either side.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X3"],"gen":"sign"},{"id":"sign-X4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X4-1\" alt=\"X4 Exit marker\" width=\"64\" height=\"64\"></div>","opts":["Road barrier","Exit marker","Post marker","Side obstacle marker"],"a":1,"ex":"X4 is <strong>Exit marker</strong> (Swedish: <i lang=\"sv\">Avfartsskärm</i>). Marks the split between a main carriageway and an exit that has a deceleration lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X4"],"gen":"sign"},{"id":"sign-X5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X5-1\" alt=\"X5 Yellow light arrow(s)\" width=\"64\" height=\"64\"></div>","opts":["Yellow light arrow(s)","Exit marker","Post marker","Road barrier"],"a":0,"ex":"X5 is <strong>Yellow light arrow(s)</strong> (Swedish: <i lang=\"sv\">Gul ljuspil eller ljuspilar</i>). Road users must pass on the side shown by the arrow or arrows, which may be flashing.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X5"],"gen":"sign"},{"id":"sign-X6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X6-1\" alt=\"X6 Special warning device\" width=\"64\" height=\"64\"></div>","opts":["Side obstacle marker","Special warning device","Temporary closure","Obstacle marker board"],"a":1,"ex":"X6 is <strong>Special warning device</strong> (Swedish: <i lang=\"sv\">Särskild varningsanordning</i>). A triangle with a text showing that the road is restricted by a temporary obstacle or similar. The text matches the reason.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X6"],"gen":"sign"},{"id":"sign-X7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X7-1\" alt=\"X7 Road barrier\" width=\"64\" height=\"64\"></div>","opts":["Side obstacle marker","Road barrier","Yellow light arrow(s)","Exit marker"],"a":1,"ex":"X7 is <strong>Road barrier</strong> (Swedish: <i lang=\"sv\">Vägbom</i>). Shows that a road is completely or partly closed to traffic. It may carry more devices to make it easier to see.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X7"],"gen":"sign"},{"id":"sign-X9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X9-1\" alt=\"X9 Roundabout centre marker\" width=\"64\" height=\"64\"></div>","opts":["Exit marker","Roundabout centre marker","Post marker","Obstacle marker board"],"a":1,"ex":"X9 is <strong>Roundabout centre marker</strong> (Swedish: <i lang=\"sv\">Cirkulationstrafik</i>). Marks the centre of a roundabout, around which vehicles must drive.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X9"],"gen":"sign"},{"id":"sign-Y1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"Y1\" alt=\"Y1 Level crossing light signal\" width=\"64\" height=\"64\"></div>","opts":["Level crossing barrier","Level crossing bell","Level crossing light signal","Level crossing marker board"],"a":2,"ex":"Y1 is <strong>Level crossing light signal</strong> (Swedish: <i lang=\"sv\">Rött blinkande ljus</i>). Two red lights flashing alternately mean stop. Road users may not pass the stop line, or the signal if there is no stop line. Below the red lights there may be a round white light that flashes to make the crossing easier to notice.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K6P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 6 kap. 6 §\">VMF 6 kap. 6 §</a>"],"signs":["Y1"],"gen":"sign"},{"id":"sign-Y3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"Y3-1\" alt=\"Y3 Level crossing barrier\" width=\"64\" height=\"64\"></div>","opts":["Level crossing light signal","Level crossing barrier","Level crossing marker board","Level crossing bell"],"a":1,"ex":"Y3 is <strong>Level crossing barrier</strong> (Swedish: <i lang=\"sv\">Bom</i>). A full or half barrier. It has at least one lamp showing flashing red light towards approaching traffic from when it starts to lower until it is fully raised. The back of the barrier may have the text “Kör genom bommen” (drive through the barrier).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K6P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 6 kap. 6 §\">VMF 6 kap. 6 §</a>"],"signs":["Y3"],"gen":"sign"}];
